import subprocess, time, os, re, json, sys
def clean(s): return re.sub(r'\x1b\[[0-9;]*m','',s)
def sc(name, sa, ca, dur=8, env=None):
    print(f"\n===== {name} =====")
    e=dict(os.environ); e.update(env or {})
    srv=subprocess.Popen(["./executable"]+sa, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, env=e)
    time.sleep(0.7)
    try:
        r=subprocess.run(["./executable"]+ca, capture_output=True, text=True, timeout=dur, env=e)
        print("CLIENT exit",r.returncode)
        out=clean(r.stdout)
        # truncate long lines
        lines=out.splitlines()
        for l in lines[:120]:
            print(l[:300])
        if len(lines)>120: print(f"... {len(lines)-120} more lines")
        print("ERR:",clean(r.stderr)[:2000])
    except subprocess.TimeoutExpired as ex:
        out=ex.stdout.decode(errors='ignore') if isinstance(ex.stdout,bytes) else (ex.stdout or '')
        print("TIMEOUT", clean(out)[:3000])
    srv.terminate()
    try:
        out=clean(srv.communicate(timeout=3)[0])
        lines=out.splitlines()
        print("SERVER lines",len(lines))
        for l in lines[:120]: print(l[:300])
    except:
        srv.kill()

if __name__=="__main__":
    which=sys.argv[1] if len(sys.argv)>1 else ""
    if which=="jsonfile":
        if os.path.exists("/tmp/out.json"): os.remove("/tmp/out.json")
        sc("jsonfile", ["server","--listen","127.0.0.1:4434"], ["client","127.0.0.1:4434","--duration","2","--interval","1","--download-size","100","--upload-size","200","--json","/tmp/out.json"])
        data=json.load(open("/tmp/out.json"))
        print("JSON keys", data.keys())
        print("start", data.get("start"))
        print("end", data.get("end"))
        print("intervals count", len(data.get("intervals",[])))
        for i,iv in enumerate(data.get("intervals",[])):
            print(i, "streams len", len(iv.get("streams",[])), "sum", iv.get("sum"), "first stream", iv["streams"][0] if iv.get("streams") else None)
    elif which=="connstats":
        sc("connstats client+server", ["server","--listen","127.0.0.1:4434","--conn-stats"], ["client","127.0.0.1:4434","--duration","1","--download-size","1000","--upload-size","1000","--conn-stats"])
    elif which=="uni":
        sc("uni only", ["server","--listen","127.0.0.1:4434"], ["client","127.0.0.1:4434","--duration","1","--download-size","100","--upload-size","200","--bi-requests","0","--uni-requests","2"])
    elif which=="bi0":
        sc("both zero", ["server","--listen","127.0.0.1:4434"], ["client","127.0.0.1:4434","--duration","1","--bi-requests","0","--uni-requests","0"])
    elif which=="down0":
        sc("download 0 upload 0", ["server","--listen","127.0.0.1:4434"], ["client","127.0.0.1:4434","--duration","1","--download-size","0","--upload-size","0"])
    elif which=="dur0":
        sc("duration 0", ["server","--listen","127.0.0.1:4434"], ["client","127.0.0.1:4434","--duration","0"], dur=5)
    elif which=="interval":
        sc("interval 2 duration 3", ["server","--listen","127.0.0.1:4434"], ["client","127.0.0.1:4434","--duration","3","--interval","2","--download-size","100","--upload-size","100"])
    elif which=="nofinish":
        # client no server
        e=dict(os.environ)
        try:
            r=subprocess.run(["./executable","client","127.0.0.1:4599","--duration","1"], capture_output=True, text=True, timeout=8, env=e)
            print("exit",r.returncode); print(clean(r.stdout)[:4000]); print(clean(r.stderr)[:2000])
        except subprocess.TimeoutExpired as ex:
            print("timeout", clean((ex.stdout or b'').decode(errors='ignore'))[:4000])
