import subprocess, time, os, re, json, sys
def clean(s): return re.sub(r'\x1b\[[0-9;]*m','',s)
def sc(name, sa, ca, dur=8, env=None, wait_after=0):
    print(f"\n===== {name} =====")
    e=dict(os.environ); e.update(env or {})
    srv=subprocess.Popen(["./executable"]+sa, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, env=e)
    time.sleep(0.7)
    try:
        r=subprocess.run(["./executable"]+ca, capture_output=True, text=True, timeout=dur, env=e)
        print("CLIENT exit",r.returncode)
        out=clean(r.stdout)
        for l in out.splitlines():
            print(l)
        print("ERR:",clean(r.stderr)[:2000])
    except subprocess.TimeoutExpired as ex:
        out=ex.stdout.decode(errors='ignore') if isinstance(ex.stdout,bytes) else (ex.stdout or '')
        print("TIMEOUT", clean(out)[:6000])
    if wait_after: time.sleep(wait_after)
    srv.terminate()
    try:
        out=clean(srv.communicate(timeout=3)[0])
        print("SERVER:")
        for l in out.splitlines(): print(l)
    except:
        srv.kill()

