    e=dict(os.environ)
    for args in [["client","127.0.0.1:4599","--duration","1"], ["client","badhost:4433","--duration","1"], ["client","localhost:4599","--duration","1"], ["client","256.256.256.256:4433"], ["client","example.com:4433"]]:
        print("ARGS",args)
        try:
            r=subprocess.run(["./executable"]+args, capture_output=True, text=True, timeout=7, env=e)
            print("exit",r.returncode); print(clean(r.stdout)[:5000]); print("ERR",clean(r.stderr)[:2000])
        except subprocess.TimeoutExpired as ex:
            print("timeout", clean((ex.stdout or b'').decode(errors='ignore'))[:5000])
elif which=="down0":
    sc("down0", ["server","--listen","127.0.0.1:4434"], ["client","127.0.0.1:4434","--duration","1","--download-size","0","--upload-size","0"])
elif which=="dur0":
    sc("dur0", ["server","--listen","127.0.0.1:4434"], ["client","127.0.0.1:4434","--duration","0"], dur=5)
elif which=="interval0":
