	switch strings.ToLower(s) {
	case "off":
		return 0, true
	case "error":
		return lvlError, true
	case "warn":
		return lvlWarn, true
	case "info":
		return lvlInfo, true
	case "debug":
		return lvlDebug, true
	case "trace":
		return lvlTrace, true
	case "0":
		return 0, true
	case "1":
		return lvlError, true
	case "2":
		return lvlWarn, true
	case "3":
		return lvlInfo, true
	case "4":
		return lvlDebug, true
	case "5":
		return lvlTrace, true
	}
	return 0, false
}

func initLog() {
	_, noColor = os.LookupEnv("NO_COLOR")
	v, ok := os.LookupEnv("RUST_LOG")
	if !ok {
		logDirectives = []logDirective{{"", lvlWarn}}
		return
	}
	logHasFilter = true
	// parse
	parts := strings.Split(v, ",")
	for _, p := range parts {
		p = strings.TrimSpace(p)
		if p == "" {
			continue
		}
		if strings.Contains(p, "[") || strings.Contains(p, "]") {
			logParseBad = true
			break
		}
		if idx := strings.Index(p, "="); idx >= 0 {
			target := p[:idx]
			ls := p[idx+1:]
			if ls == "" || target == "" {
				// mimic observed: "info=" yields no useful directive but not fallback; treat as target directive trace? Actually info= gave no logs.
				// treat as invalid-ish: add nothing
				continue
			}
			lvl, ok := parseLevel(ls)
			if !ok {
				logParseBad = true
				break
			}
			logDirectives = append(logDirectives, logDirective{target, lvl})
