	for _, r := range s {
		if (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') || r == '_' || r == ':' || r == '-' || r == '.' {
			continue
		}
		return false
	}
	return len(s) > 0
}

func logEnabled(level int, target string) bool {
	if logParseBad {
		return level <= lvlWarn
	}
	if logHasFilter && len(logDirectives) == 0 {
		return false
	}
	bestLen := -1
	bestLevel := -1
	globalLevel := -1
	for _, d := range logDirectives {
		if d.target == "" {
			globalLevel = d.level
			continue
		}
		if target == d.target || strings.HasPrefix(target, d.target+"::") {
			if len(d.target) > bestLen {
				bestLen = len(d.target)
				bestLevel = d.level
			}
		}
	}
	use := globalLevel
	if bestLevel >= 0 {
