		return "TRACE"
	}
}
func levelColor(level int) string {
	switch level {
	case lvlError:
		return "31"
	case lvlWarn:
		return "33"
	case lvlInfo:
		return "32"
	case lvlDebug:
		return "34"
	case lvlTrace:
		return "35" // magenta, tracing uses purple
	}
	return "0"
}

func logLine(level int, target, msg string) {
	if !logEnabled(level, target) {
		return
	}
	ts := time.Now().UTC().Format("2006-01-02T15:04:05.000000Z")
	name := levelName(level)
	// right-align width 5
	padded := fmt.Sprintf("%5s", name)
	logMu.Lock()
	defer logMu.Unlock()
	if noColor {
		fmt.Fprintf(os.Stdout, "%s %s %s: %s\n", ts, padded, target, msg)
	} else {
