func logWarn(target, msg string)  { logLine(lvlWarn, target, msg) }
func logInfo(target, msg string)  { logLine(lvlInfo, target, msg) }
func logDebug(target, msg string) { logLine(lvlDebug, target, msg) }

// main error: target quinn_perf, then program returns (exit 0)
func mainError(err error) {
	if err == nil {
		return
	}
	logError("quinn_perf", err.Error())
}

func rustPanic(location, msg string) {
	// print to stderr like Rust panic, exit 101
	tid := os.Getpid()
	bt := os.Getenv("RUST_BACKTRACE")
	fmt.Fprintf(os.Stderr, "\nthread 'main' (%d) panicked at %s:\n%s\n", tid, location, msg)
	if bt == "1" {
		fmt.Fprintf(os.Stderr, "stack backtrace:\nnote: Some details are omitted, run with `RUST_BACKTRACE=full` for a verbose backtrace.\n")
	} else if bt != "" && bt != "0" {
		// full or other
		if bt == "full" {
			fmt.Fprintf(os.Stderr, "stack backtrace:\n   0:     0x000000000000 - <unknown>\nnote: Some details are omitted, run with `RUST_BACKTRACE=full` for a verbose backtrace.\n")
		} else {
			fmt.Fprintf(os.Stderr, "stack backtrace:\nnote: Some details are omitted, run with `RUST_BACKTRACE=full` for a verbose backtrace.\n")
		}
	} else {
		fmt.Fprintf(os.Stderr, "note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
	}
	os.Exit(101)
}
