func rustPanic(location, msg string) {
	// print to stderr like Rust panic, exit 101
	tid := os.Getpid()
	bt := os.Getenv("RUST_BACKTRACE")
	fmt.Fprintf(os.Stderr, "\nthread 'main' (%d) panicked at %s:\n%s\n", tid, location, msg)
	if bt == "1" {
		fmt.Fprintf(os.Stderr, "stack backtrace:\nnote: Some details are omitted, run with `RUST_BACKTRACE=full` for a verbose backtrace.\n")
	} else if bt != "" && bt != "0" {
