// jaro similarity
func jaro(a, b string) float64 {
	ar := []rune(a)
	br := []rune(b)
	if len(ar) == 0 || len(br) == 0 {
		return 0
	}
	matchDist := len(ar)
	if len(br) > matchDist {
		matchDist = len(br)
	}
	matchDist = matchDist/2 - 1
	if matchDist < 0 {
		matchDist = 0
	}
	aMatches := make([]bool, len(ar))
	bMatches := make([]bool, len(br))
	matches := 0
	for i, ra := range ar {
		start := i - matchDist
		if start < 0 {
			start = 0
		}
		end := i + matchDist + 1
		if end > len(br) {
			end = len(br)
		}
		for j := start; j < end; j++ {
			if !bMatches[j] && ra == br[j] {
				aMatches[i] = true
				bMatches[j] = true
				matches++
				break
			}
		}
	}
	if matches == 0 {
		return 0
	}
	t := 0
	k := 0
	for i := range ar {
		if aMatches[i] {
			for !bMatches[k] {
				k++
			}
			if ar[i] != br[k] {
				t++
			}
			k++
		}
	}
	m := float64(matches)
	return (m/float64(len(ar)) + m/float64(len(br)) + (m-float64(t)/2)/m) / 3
