				cli.Host = tok
				hostSet = true
			} else {
				exitClap(fmt.Sprintf("unexpected argument '%s' found", tok), "", usageServer())
			}
			continue
		}
		if tok == "--" {
			afterDD = true
			continue
		}
		if strings.HasPrefix(tok, "--") {
			eq := strings.Index(tok, "=")
			name := tok[2:]
			var inline *string
			if eq >= 0 {
				name = tok[2:eq]
				v := tok[eq+1:]
				inline = &v
			}
			if name == "help" {
				if inline != nil {
					exitClap(fmt.Sprintf("unexpected value '%s' for '--help' found; no more were expected", *inline), "", usageFor(sub))
				}
				if sub == "server" {
					printOut(serverHelpLong)
				} else {
					printOut(clientHelpLong)
				}
				os.Exit(0)
			}
			s, ok := specByLong[name]
			if !ok {
				unknownArgError(sub, "--"+name, specs)
			}
			checkDup(s)
			if s.isFlag {
				if inline != nil {
					usage := ""
					if sub == "client" {
						usage = fmt.Sprintf("{BIN} client %s [HOST]", specUsage(s))
					} else {
						usage = fmt.Sprintf("{BIN} server %s", specUsage(s))
					}
					exitClap(fmt.Sprintf("unexpected value '%s' for '%s' found; no more were expected", *inline, specUsage(s)), "", usage)
				}
				assignFlag(sub, s, srv, cli)
			} else {
				v := getValue(s, inline, &i)
				assignValue(sub, nil, s, v, srv, cli)
			}
			continue
		}
		if strings.HasPrefix(tok, "-") && len(tok) > 1 {
			// short cluster
			j := 1
			consumedValue := false
			for j < len(tok) {
				c := tok[j]
				if c == 'h' {
					if sub == "server" {
						printOut(serverHelpShort)
					} else {
						printOut(clientHelpShort)
					}
					os.Exit(0)
				}
				s, ok := specByShort[c]
				if !ok {
					unknownArgError(sub, "-"+string(c), specs)
				}
				checkDup(s)
				// value-taking
				var v string
				if j+1 < len(tok) {
					v = tok[j+1:]
					assignValue(sub, nil, s, v, srv, cli)
				} else {
					v = getValue(s, nil, &i)
					assignValue(sub, nil, s, v, srv, cli)
				}
				consumedValue = true
				break
			}
			_ = consumedValue
			continue
		}
		// positional
		if sub == "client" {
			if hostSet {
				exitClap(fmt.Sprintf("unexpected argument '%s' found", tok), "", usageClient())
			}
			cli.Host = tok
			hostSet = true
		} else {
			exitClap(fmt.Sprintf("unexpected argument '%s' found", tok), "", usageServer())
		}
	}
	if sub == "server" {
		if srv.KeySet != srv.CertSet {
			missing := "--cert <CERT>"
			missingSpec := "--cert <CERT>"
			presentSpec := "--key <KEY>"
			if srv.CertSet {
				missing = "--key <KEY>"
				missingSpec = "--key <KEY>"
				presentSpec = "--cert <CERT>"
			}
			// Build message
			var b strings.Builder
			b.WriteString("error: the following required arguments were not provided:\n  " + missing + "\n")
			b.WriteString("\nUsage: {BIN} server " + presentSpec + " " + missingSpec + "\n")
			b.WriteString("\nFor more information, try '--help'.\n")
			fmt.Fprint(os.Stderr, substBin(b.String()))
			os.Exit(2)
			_ = presentOrder
		}
		return srv, nil
	}
	return nil, cli
}

func parseTop(args []string) (string, *ServerOpts, *ClientOpts) {
	if len(args) == 0 {
		fmt.Fprint(os.Stderr, substBin(mainHelp))
		os.Exit(2)
	}
	first := args[0]
	if first == "-h" || first == "--help" {
		printOut(mainHelp)
		os.Exit(0)
	}
	if first == "help" {
		rest := args[1:]
		if len(rest) == 0 {
			printOut(mainHelp)
			os.Exit(0)
		}
		// traverse
		if rest[0] == "server" || rest[0] == "client" {
			if len(rest) > 1 {
				exitClap(fmt.Sprintf("unrecognized subcommand '%s'", rest[1]), "", usageFor(rest[0]))
			}
			if rest[0] == "server" {
				printOut(serverHelpLong)
			} else {
				printOut(clientHelpLong)
			}
			os.Exit(0)
		}
		if rest[0] == "help" {
			if len(rest) > 1 {
				// help help <...> : clap prints help for help? approximate error
				// try: if second is a known ... keep simple
				printOut(helpHelp)
				os.Exit(0)
			}
			printOut(helpHelp)
			os.Exit(0)
		}
		// unrecognized
		tip := ""
		if sim := didYouMean(rest[0], []string{"server", "client", "help"}); sim != "" {
			tip = fmt.Sprintf("a similar subcommand exists: '%s'", sim)
		}
		exitClap(fmt.Sprintf("unrecognized subcommand '%s'", rest[0]), tip, usageMain())
	}
	if first == "server" || first == "client" {
		srv, cli := parseSubArgs(first, args[1:])
		return first, srv, cli
	}
	if first == "--" {
		if len(args) > 1 {
			next := args[1]
			tip := ""
			if next == "server" || next == "client" || next == "help" {
				tip = fmt.Sprintf("subcommand '%s' exists; to use it, remove the '--' before it", next)
			}
			exitClap(fmt.Sprintf("unexpected argument '%s' found", next), tip, usageMain())
		}
		fmt.Fprint(os.Stderr, substBin(mainHelp))
		os.Exit(2)
	}
	if strings.HasPrefix(first, "-") {
		// unknown argument at top
		display := first
		if strings.HasPrefix(first, "--") {
			if idx := strings.Index(first, "="); idx >= 0 {
				display = first[:idx]
			}
		}
		exitClap(fmt.Sprintf("unexpected argument '%s' found", display), "", usageMain())
	}
	// unrecognized subcommand
	tip := ""
	if sim := didYouMean(first, []string{"server", "client", "help"}); sim != "" {
		tip = fmt.Sprintf("a similar subcommand exists: '%s'", sim)
	}
	exitClap(fmt.Sprintf("unrecognized subcommand '%s'", first), tip, usageMain())
	return "", nil, nil
}
