func parseU64Rust(s string) (uint64, string) {
	if s == "" {
		return 0, "cannot parse integer from empty string"
	}
	t := s
	if strings.HasPrefix(t, "+") {
		t = t[1:]
		if t == "" {
			return 0, "invalid digit found in string"
		}
	}
	for _, c := range t {
		if c < '0' || c > '9' {
			return 0, "invalid digit found in string"
		}
	}
	// overflow check
	tt := strings.TrimLeft(t, "0")
	if tt == "" {
		return 0, ""
	}
	if len(tt) > 20 || (len(tt) == 20 && tt > "18446744073709551615") {
		return 0, "number too large to fit in target type"
	}
	v, err := strconv.ParseUint(tt, 10, 64)
	if err != nil {
		return 0, "number too large to fit in target type"
	}
	return v, ""
}
func parseI64RangedU16(s string) (uint16, string) {
	if s == "" {
		return 0, "cannot parse integer from empty string"
	}
	t := s
	neg := false
	if strings.HasPrefix(t, "+") {
		t = t[1:]
	} else if strings.HasPrefix(t, "-") {
		neg = true
		t = t[1:]
	}
	if t == "" {
		return 0, "invalid digit found in string"
	}
	for _, c := range t {
		if c < '0' || c > '9' {
			return 0, "invalid digit found in string"
		}
	}
	tt := strings.TrimLeft(t, "0")
	if tt == "" {
		return 0, "" // -0 or +0
	}
	// i64 overflow
	limit := "9223372036854775807"
	if neg {
		limit = "9223372036854775808"
	}
	if len(tt) > 19 || (len(tt) == 19 && tt > limit) {
		return 0, "number too large to fit in target type"
	}
	v, _ := strconv.ParseInt(s, 10, 64)
	if v < 0 || v > 65535 {
		return 0, fmt.Sprintf("%d is not in 0..=65535", v)
	}
	return uint16(v), ""
}
func parseByteSize(s string) (uint64, string) {
	t := strings.TrimSpace(s)
	factor := uint64(1)
	num := t
	if len(t) > 0 {
		switch t[len(t)-1] {
		case 'k':
			factor = 1024
			num = t[:len(t)-1]
		case 'M':
			factor = 1024 * 1024
			num = t[:len(t)-1]
		case 'G':
			factor = 1024 * 1024 * 1024
			num = t[:len(t)-1]
		case 'T':
			factor = 1024 * 1024 * 1024 * 1024
			num = t[:len(t)-1]
		}
	}
	v, reason := parseU64Rust(num)
	if reason != "" {
		return 0, reason
	}
	return v * factor, "" // wrapping in Go for uint64
}

func validSocketAddr(s string) bool {
	// Rust SocketAddr parse
	if strings.HasPrefix(s, "[") {
		end := strings.Index(s, "]")
		if end < 0 {
			return false
		}
		ipStr := s[1:end]
		rest := s[end+1:]
		if !strings.HasPrefix(rest, ":") {
			return false
		}
		portStr := rest[1:]
		if _, reason := parseI64RangedU16(portStr); reason != "" {
			// Rust port is u16 parse: + allowed, but range same; empty/invalid fails
			// However values like 65536 fail too; all are invalid socket addr syntax
			return false
		}
		// zone?
		if idx := strings.Index(ipStr, "%"); idx >= 0 {
			if idx == len(ipStr)-1 {
				return false
			}
			ipStr = ipStr[:idx]
		}
		ip := net.ParseIP(ipStr)
		return ip != nil && strings.Contains(ipStr, ":")
	}
	// IPv4
	idx := strings.LastIndex(s, ":")
	if idx < 0 {
		return false
	}
	host := s[:idx]
	portStr := s[idx+1:]
	if strings.Contains(host, ":") {
		return false
	}
	if _, reason := parseI64RangedU16(portStr); reason != "" {
		return false
	}
	ip := net.ParseIP(host)
	return ip != nil && strings.Contains(host, ".")
}
func validIP(s string) bool {
	if s == "" || strings.Contains(s, "%") || strings.Contains(s, "[") || strings.Contains(s, "]") {
		return false
	}
	ip := net.ParseIP(s)
	if ip == nil {
		return false
	}
	// Go accepts some forms Rust doesn't? Ensure IPv4 octets no leading zeros beyond single zero; ParseIP already rejects leading zeros in recent Go.
	return true
}

