			if sub == "server" { srv.InitialMtu = v } else { cli.InitialMtu = v }
		} else {
			if sub == "server" { srv.MaxUdpPayloadSize = v } else { cli.MaxUdpPayloadSize = v }
		}
	case "uni-requests", "bi-requests", "duration", "interval", "initial-rtt":
		v, reason := parseU64Rust(val)
		if reason != "" {
			invalidValueExit(sub, val, s, reason)
		}
		switch s.long {
		case "uni-requests": cli.UniRequests = v
		case "bi-requests": cli.BiRequests = v
		case "duration": cli.Duration = v
		case "interval": cli.Interval = v
		case "initial-rtt":
			if sub == "server" { srv.InitialRtt = &v } else { p:=v; cli.InitialRtt=&p }
		}
	case "congestion":
		if val != "cubic" && val != "bbr" && val != "new-reno" {
			invalidValueExit(sub, val, s, "")
		}
		if sub == "server" { srv.Congestion = val } else { cli.Congestion = val }
	case "qlog":
		if sub == "server" { srv.Qlog = val; srv.QlogSet = true } else { cli.Qlog = val; cli.QlogSet = true }
	case "json":
		cli.Json = val
		cli.JsonSet = true
	}
}
func assignFlag(sub string, s optSpec, srv *ServerOpts, cli *ClientOpts) {
	setBool := func(dst **bool) {}
	_ = setBool
	switch s.long {
	case "conn-stats":
		if sub == "server" { srv.ConnStats = true } else { cli.ConnStats = true }
	case "keylog":
		if sub == "server" { srv.Keylog = true } else { cli.Keylog = true }
	case "no-protection":
		if sub == "server" { srv.NoProtection = true } else { cli.NoProtection = true }
	case "ack-frequency":
		if sub == "server" { srv.AckFrequency = true } else { cli.AckFrequency = true }
	}
}

func unknownArgError(sub, display string, specs []optSpec) {
	// display e.g. --unknown or -x or foo
	tip := ""
	usage := usageFor(sub)
	// similar long argument?
	if strings.HasPrefix(display, "--") {
		name := display[2:]
		cands := []string{}
		candSpec := map[string]optSpec{}
		for _, sp := range specs {
			cands = append(cands, sp.long)
			candSpec[sp.long] = sp
		}
		if sim := didYouMean(name, cands); sim != "" {
			tip = fmt.Sprintf("a similar argument exists: '--%s'", sim)
			sp := candSpec[sim]
			if sub == "client" {
				usage = fmt.Sprintf("{BIN} client %s [HOST]", specUsage(sp))
			} else if sub == "server" {
				usage = fmt.Sprintf("{BIN} server %s", specUsage(sp))
			}
			exitClap(fmt.Sprintf("unexpected argument '%s' found", display), tip, usage)
		}
	}
	if sub == "client" {
		tip = fmt.Sprintf("to pass '%s' as a value, use '-- %s'", display, display)
	}
	exitClap(fmt.Sprintf("unexpected argument '%s' found", display), tip, usage)
}

func parseSubArgs(sub string, args []string) (*ServerOpts, *ClientOpts) {
	specs := serverSpecs()
	if sub == "client" {
		specs = clientSpecs()
	}
	specByLong := map[string]optSpec{}
	specByShort := map[byte]optSpec{}
	for _, sp := range specs {
		specByLong[sp.long] = sp
		if sp.short != 0 {
			specByShort[sp.short] = sp
		}
	}
	srv := &ServerOpts{Listen: "[::]:4433"}
	cli := &ClientOpts{Host: "localhost:4433", UniRequests: 0, BiRequests: 1, DownloadSize: 1048576, UploadSize: 1048576, Duration: 60, Interval: 1}
	// defaults common
	defCommon := CommonOpts{SendBufferSize: 2097152, RecvBufferSize: 2097152, InitialMtu: 1200, MaxUdpPayloadSize: 1472}
	srv.CommonOpts = defCommon
	cli.CommonOpts = defCommon

	seen := map[string]bool{}
	presentOrder := []optSpec{}
	hostSet := false
	afterDD := false

	isKnownToken := func(tok string) bool {
		if tok == "--" || tok == "-h" || tok == "--help" {
			return true
		}
		if strings.HasPrefix(tok, "--") {
			name := tok[2:]
			if idx := strings.Index(name, "="); idx >= 0 {
				name = name[:idx]
			}
			_, ok := specByLong[name]
			return ok || name == "help"
		}
		if strings.HasPrefix(tok, "-") && len(tok) > 1 {
			c := tok[1]
			if c == 'h' {
				return true
			}
			_, ok := specByShort[c]
			return ok
		}
		return false
	}
	unknownDisplay := func(tok string) string {
		if strings.HasPrefix(tok, "--") {
			name := tok
			if idx := strings.Index(name, "="); idx >= 0 {
				name = name[:idx]
			}
			return name
		}
		return tok
	}

	getValue := func(s optSpec, inline *string, idx *int) string {
		if inline != nil {
			return *inline
		}
		// need next
		if *idx+1 >= len(args) {
			exitClap(fmt.Sprintf("a value is required for '%s' but none was supplied", specUsage(s)), "", "")
		}
		next := args[*idx+1]
		if strings.HasPrefix(next, "-") && len(next) > 1 {
			if isKnownToken(next) {
				exitClap(fmt.Sprintf("a value is required for '%s' but none was supplied", specUsage(s)), "", "")
			} else {
				unknownArgError(sub, unknownDisplay(next), specs)
			}
		}
		*idx++
		return next
	}
	checkDup := func(s optSpec) {
		if seen[s.long] {
			exitClap(fmt.Sprintf("the argument '%s' cannot be used multiple times", specUsage(s)), "", usageFor(sub))
		}
		seen[s.long] = true
		presentOrder = append(presentOrder, s)
	}

	for i := 0; i < len(args); i++ {
		tok := args[i]
		if afterDD {
			// positional
			if sub == "client" {
				if hostSet {
					exitClap(fmt.Sprintf("unexpected argument '%s' found", tok), "", usageClient())
				}
				cli.Host = tok
				hostSet = true
			} else {
				exitClap(fmt.Sprintf("unexpected argument '%s' found", tok), "", usageServer())
			}
			continue
		}
		if tok == "--" {
			afterDD = true
			continue
		}
		if strings.HasPrefix(tok, "--") {
			eq := strings.Index(tok, "=")
			name := tok[2:]
			var inline *string
			if eq >= 0 {
				name = tok[2:eq]
				v := tok[eq+1:]
				inline = &v
			}
			if name == "help" {
				if inline != nil {
					exitClap(fmt.Sprintf("unexpected value '%s' for '--help' found; no more were expected", *inline), "", usageFor(sub))
				}
				if sub == "server" {
					printOut(serverHelpLong)
				} else {
					printOut(clientHelpLong)
				}
				os.Exit(0)
			}
			s, ok := specByLong[name]
			if !ok {
				unknownArgError(sub, "--"+name, specs)
			}
			checkDup(s)
			if s.isFlag {
				if inline != nil {
					usage := ""
					if sub == "client" {
						usage = fmt.Sprintf("{BIN} client %s [HOST]", specUsage(s))
					} else {
						usage = fmt.Sprintf("{BIN} server %s", specUsage(s))
					}
					exitClap(fmt.Sprintf("unexpected value '%s' for '%s' found; no more were expected", *inline, specUsage(s)), "", usage)
				}
				assignFlag(sub, s, srv, cli)
			} else {
				v := getValue(s, inline, &i)
				assignValue(sub, nil, s, v, srv, cli)
			}
			continue
		}
		if strings.HasPrefix(tok, "-") && len(tok) > 1 {
			// short cluster
			j := 1
			consumedValue := false
			for j < len(tok) {
				c := tok[j]
				if c == 'h' {
					if sub == "server" {
						printOut(serverHelpShort)
					} else {
						printOut(clientHelpShort)
					}
					os.Exit(0)
				}
				s, ok := specByShort[c]
				if !ok {
					unknownArgError(sub, "-"+string(c), specs)
				}
				checkDup(s)
				// value-taking
				var v string
				if j+1 < len(tok) {
					v = tok[j+1:]
					assignValue(sub, nil, s, v, srv, cli)
				} else {
					v = getValue(s, nil, &i)
					assignValue(sub, nil, s, v, srv, cli)
				}
				consumedValue = true
				break
			}
			_ = consumedValue
			continue
		}
		// positional
		if sub == "client" {
			if hostSet {
				exitClap(fmt.Sprintf("unexpected argument '%s' found", tok), "", usageClient())
			}
			cli.Host = tok
			hostSet = true
		} else {
			exitClap(fmt.Sprintf("unexpected argument '%s' found", tok), "", usageServer())
		}
	}
	if sub == "server" {
		if srv.KeySet != srv.CertSet {
			missing := "--cert <CERT>"
			missingSpec := "--cert <CERT>"
			presentSpec := "--key <KEY>"
			if srv.CertSet {
				missing = "--key <KEY>"
				missingSpec = "--key <KEY>"
				presentSpec = "--cert <CERT>"
			}
			// Build message
			var b strings.Builder
			b.WriteString("error: the following required arguments were not provided:\n  " + missing + "\n")
			b.WriteString("\nUsage: {BIN} server " + presentSpec + " " + missingSpec + "\n")
			b.WriteString("\nFor more information, try '--help'.\n")
			fmt.Fprint(os.Stderr, substBin(b.String()))
			os.Exit(2)
			_ = presentOrder
		}
		return srv, nil
	}
	return nil, cli
}

func parseTop(args []string) (string, *ServerOpts, *ClientOpts) {
	if len(args) == 0 {
		fmt.Fprint(os.Stderr, substBin(mainHelp))
		os.Exit(2)
	}
	first := args[0]
	if first == "-h" || first == "--help" {
		printOut(mainHelp)
		os.Exit(0)
	}
	if first == "help" {
		rest := args[1:]
		if len(rest) == 0 {
			printOut(mainHelp)
			os.Exit(0)
		}
		// traverse
		if rest[0] == "server" || rest[0] == "client" {
			if len(rest) > 1 {
				exitClap(fmt.Sprintf("unrecognized subcommand '%s'", rest[1]), "", usageFor(rest[0]))
			}
			if rest[0] == "server" {
				printOut(serverHelpLong)
			} else {
				printOut(clientHelpLong)
			}
			os.Exit(0)
		}
		if rest[0] == "help" {
			if len(rest) > 1 {
				// help help <...> : clap prints help for help? approximate error
				// try: if second is a known ... keep simple
				printOut(helpHelp)
				os.Exit(0)
			}
			printOut(helpHelp)
			os.Exit(0)
		}
		// unrecognized
		tip := ""
		if sim := didYouMean(rest[0], []string{"server", "client", "help"}); sim != "" {
			tip = fmt.Sprintf("a similar subcommand exists: '%s'", sim)
		}
		exitClap(fmt.Sprintf("unrecognized subcommand '%s'", rest[0]), tip, usageMain())
	}
	if first == "server" || first == "client" {
		srv, cli := parseSubArgs(first, args[1:])
		return first, srv, cli
	}
	if first == "--" {
		if len(args) > 1 {
			next := args[1]
			tip := ""
			if next == "server" || next == "client" || next == "help" {
				tip = fmt.Sprintf("subcommand '%s' exists; to use it, remove the '--' before it", next)
			}
			exitClap(fmt.Sprintf("unexpected argument '%s' found", next), tip, usageMain())
		}
		fmt.Fprint(os.Stderr, substBin(mainHelp))
		os.Exit(2)
	}
	if strings.HasPrefix(first, "-") {
		// unknown argument at top
		display := first
		if strings.HasPrefix(first, "--") {
			if idx := strings.Index(first, "="); idx >= 0 {
				display = first[:idx]
			}
		}
		exitClap(fmt.Sprintf("unexpected argument '%s' found", display), "", usageMain())
	}
	// unrecognized subcommand
	tip := ""
	if sim := didYouMean(first, []string{"server", "client", "help"}); sim != "" {
		tip = fmt.Sprintf("a similar subcommand exists: '%s'", sim)
	}
	exitClap(fmt.Sprintf("unrecognized subcommand '%s'", first), tip, usageMain())
	return "", nil, nil
}
