func rustOsError(err error) string {
	// Extract errno if possible
	if pe, ok := err.(*os.PathError); ok {
		err = pe.Err
	}
	if errno, ok := err.(syscall.Errno); ok {
		msg := errno.Error()
		// Capitalize first letter to match Rust/libc strerror style
		if len(msg) > 0 {
			msg = strings.ToUpper(msg[:1]) + msg[1:]
		}
		// Go strings differ for some
		switch int(errno) {
		case 21:
			msg = "Is a directory"
		case 20:
			msg = "Not a directory"
		case 2:
			msg = "No such file or directory"
		case 13:
			msg = "Permission denied"
		case 98:
			msg = "Address already in use"
		}
		return fmt.Sprintf("%s (os error %d)", msg, int(errno))
	}
	return err.Error()
}

type pemBlock struct {
	Label string
	DER   []byte
}

// parse PEM blocks in rustls_pemfile-like fashion. Returns blocks and possibly a base64 error string.
func scanPEM(data []byte) ([]pemBlock, string) {
	text := string(data)
	var blocks []pemBlock
	for {
		idx := strings.Index(text, "-----BEGIN ")
		if idx < 0 {
			break
		}
		rest := text[idx+len("-----BEGIN "):]
		endLabel := strings.Index(rest, "-----")
		if endLabel < 0 {
			// malformed; rustls_pemfile might error, approximate no items further
			break
		}
		label := strings.TrimSpace(rest[:endLabel])
		body := rest[endLabel+len("-----"):]
		endMarker := "-----END " + label + "-----"
		endIdx := strings.Index(body, endMarker)
		if endIdx < 0 {
			break
		}
		b64text := body[:endIdx]
		// Strip PEM headers (lines containing ':' before blank line) similar to pem parser: rustls_pemfile doesn't support headers?
		// Remove whitespace
		var compact []byte
		for i := 0; i < len(b64text); i++ {
			c := b64text[i]
			if c == '\n' || c == '\r' || c == ' ' || c == '\t' {
				continue
			}
			compact = append(compact, c)
		}
		// If headers present, compact will contain ':' etc and trigger invalid char (acceptable approx)
		der, err := base64.StdEncoding.DecodeString(string(compact))
		if err != nil {
			// Find invalid character
			for _, c := range compact {
				if !((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '+' || c == '/' || c == '=') {
					return blocks, fmt.Sprintf("base64 decode error: InvalidCharacter(%d)", c)
				}
			}
			// padding/length errors
			if strings.Contains(err.Error(), "illegal base64 data") {
				// Rust base64 InvalidLength etc; approximate
				return blocks, "base64 decode error: InvalidLength"
			}
			return blocks, "base64 decode error: " + err.Error()
		}
		blocks = append(blocks, pemBlock{Label: label, DER: der})
		text = body[endIdx+len(endMarker):]
	}
	return blocks, ""
}

// Returns private key DER item (first recognized), and an error string to be used after "reading private key: "
func readPrivateKeyFile(path string) ([]byte, string, string) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, "", "I/O error: " + rustOsError(err)
	}
	blocks, b64err := scanPEM(data)
	// rustls_pemfile::private_key scans: if it hits a base64 error before a key, error takes precedence.
	// Approximation: if b64err and no key block before it -- our scanPEM returns blocks before error, so check order simplified:
	// If there is a key in blocks, use it even if later error (likely private_key returns early).
	for _, b := range blocks {
		if b.Label == "PRIVATE KEY" || b.Label == "RSA PRIVATE KEY" || b.Label == "EC PRIVATE KEY" {
			return b.DER, b.Label, ""
		}
	}
	if b64err != "" {
		return nil, "", b64err
	}
	return nil, "", "no items found"
}

func readCertChainFile(path string) ([][]byte, string, bool) {
	// bool indicates error should use "file" prefix vs plain prefix
	data, err := os.ReadFile(path)
	if err != nil {
		// Distinguish missing/open errors vs read errors: check if file exists
		if _, serr := os.Stat(path); serr != nil {
			return nil, "I/O error: " + rustOsError(err), true
		}
		return nil, "I/O error: " + rustOsError(err), false
	}
	blocks, b64err := scanPEM(data)
	var certs [][]byte
	for _, b := range blocks {
		if b.Label == "CERTIFICATE" {
			certs = append(certs, b.DER)
		}
	}
	if b64err != "" && len(certs) == 0 {
		return nil, b64err, false
	}
	// If certs found, ignore later errors approx.
	return certs, "", false
}

func parsePrivateKeyAny(der []byte, label string) (crypto.Signer, error) {
	// Try PKCS8, then PKCS1, then SEC1, then Ed25519 PKCS8 raw
	if k, err := x509.ParsePKCS8PrivateKey(der); err == nil {
		if signer, ok := k.(crypto.Signer); ok {
			return signer, nil
		}
		return nil, fmt.Errorf("unsupported pkcs8")
	}
	if k, err := x509.ParsePKCS1PrivateKey(der); err == nil {
		return k, nil
	}
	if k, err := x509.ParseECPrivateKey(der); err == nil {
		return k, nil
	}
	return nil, fmt.Errorf("failed to parse")
}

func publicKeysEqual(a, b crypto.PublicKey) bool {
	switch av := a.(type) {
	case *rsa.PublicKey:
		bv, ok := b.(*rsa.PublicKey)
		if !ok {
			return false
		}
		return av.N.Cmp(bv.N) == 0 && av.E == bv.E
	case *ecdsa.PublicKey:
		bv, ok := b.(*ecdsa.PublicKey)
		if !ok {
			return false
		}
		return av.Curve == bv.Curve && av.X.Cmp(bv.X) == 0 && av.Y.Cmp(bv.Y) == 0
	case ed25519.PublicKey:
		bv, ok := b.(ed25519.PublicKey)
		if !ok {
			return false
		}
		return bytes.Equal(av, bv)
	default:
		return false
	}
}

func generateSelfSigned() ([][]byte, crypto.Signer, error) {
	priv, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		return nil, nil, err
	}
	serialBytes := make([]byte, 16)
	_, _ = rand.Read(serialBytes)
	serial := new(big.Int).SetBytes(serialBytes)
	if serial.Sign() == 0 {
		serial.SetInt64(1)
	}
	tmpl := &x509.Certificate{
		SerialNumber: serial,
		Subject:      pkix.Name{},
		NotBefore:    time.Date(1975, 1, 1, 0, 0, 0, 0, time.UTC),
		NotAfter:     time.Date(4096, 1, 1, 0, 0, 0, 0, time.UTC),
		DNSNames:     []string{"localhost"},
		KeyUsage:     x509.KeyUsageDigitalSignature,
		ExtKeyUsage:  []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth},
		BasicConstraintsValid: true,
	}
	der, err := x509.CreateCertificate(rand.Reader, tmpl, tmpl, &priv.PublicKey, priv)
	if err != nil {
		return nil, nil, err
	}
	return [][]byte{der}, priv, nil
}

// Load server cert/key per original behavior; may call rustPanic for rustls errors.
func loadServerCert(opts *ServerOpts) ([][]byte, crypto.Signer) {
	if !opts.KeySet {
		certs, signer, err := generateSelfSigned()
		if err != nil {
			// should not happen
			panic(err)
		}
		return certs, signer
	}
	keyDER, keyLabel, kerrStr := readPrivateKeyFile(opts.Key)
	if kerrStr != "" {
		// main error return: reading private key: ...
		// caller handles via error value; we encode as special error
		panic(loadError{msg: "reading private key: " + kerrStr})
	}
	certs, cerrStr, filePrefix := readCertChainFile(opts.Cert)
	if cerrStr != "" {
		if filePrefix {
			panic(loadError{msg: "reading certificate chain file: " + cerrStr})
		} else {
			panic(loadError{msg: "reading certificate chain: " + cerrStr})
		}
	}
	// rustls with_single_cert validation at server.rs:58
	signer, err := parsePrivateKeyAny(keyDER, keyLabel)
	if err != nil {
		rustPanic("/workspace/perf/src/server.rs:58:10", "called `Result::unwrap()` on an `Err` value: General(\"failed to parse private key as RSA, ECDSA, or EdDSA\")")
	}
	if len(certs) == 0 {
		rustPanic("/workspace/perf/src/server.rs:58:10", "called `Result::unwrap()` on an `Err` value: NoCertificatesPresented")
	}
	// parse first cert (and others?)
	var firstCert *x509.Certificate
	for i, cder := range certs {
		c, err := x509.ParseCertificate(cder)
		if err != nil {
			rustPanic("/workspace/perf/src/server.rs:58:10", "called `Result::unwrap()` on an `Err` value: InvalidCertificate(BadEncoding)")
		}
		if i == 0 {
			firstCert = c
		}
	}
	if !publicKeysEqual(signer.Public(), firstCert.PublicKey) {
		rustPanic("/workspace/perf/src/server.rs:58:10", "called `Result::unwrap()` on an `Err` value: InconsistentKeys(KeyMismatch)")
	}
	return certs, signer
}

type loadError struct{ msg string }

func (e loadError) Error() string { return e.msg }
EOF
gofmt -w certs.go; echo ok"}

