type cipherSuite struct {
	id     uint16
	hash   crypto.Hash
	keyLen int
}

var (
	suiteAES128 = &cipherSuite{0x1301, crypto.SHA256, 16}
	suiteAES256 = &cipherSuite{0x1302, crypto.SHA384, 32}
	suiteChaCha = &cipherSuite{0x1303, crypto.SHA256, 32} // not implemented for AEAD; not offered/selected
