func hashBytes(h crypto.Hash, data []byte) []byte {
	if h == crypto.SHA384 {
		s := sha512.Sum384(data)
		return s[:]
	}
	s := sha256.Sum256(data)
	return s[:]
}
func hashNew(h crypto.Hash) hash.Hash {
	if h == crypto.SHA384 {
		return sha512.New384()
	}
	return sha256.New()
}
func hkdfExtract(h crypto.Hash, salt, ikm []byte) []byte {
	if salt == nil {
		salt = make([]byte, h.Size())
	}
	mac := hmac.New(func() hash.Hash { return hashNew(h) }, salt)
	mac.Write(ikm)
	return mac.Sum(nil)
}
func hkdfExpand(h crypto.Hash, secret, info []byte, length int) []byte {
	var out, t []byte
	counter := byte(1)
	for len(out) < length {
		mac := hmac.New(func() hash.Hash { return hashNew(h) }, secret)
		mac.Write(t)
		mac.Write(info)
		mac.Write([]byte{counter})
		t = mac.Sum(nil)
		out = append(out, t...)
		counter++
	}
	return out[:length]
}
func hkdfExpandLabel(h crypto.Hash, secret []byte, label string, context []byte, length int) []byte {
	fullLabel := "tls13 " + label
	var info bytes.Buffer
	_ = binary.Write(&info, binary.BigEndian, uint16(length))
	info.WriteByte(byte(len(fullLabel)))
	info.WriteString(fullLabel)
	info.WriteByte(byte(len(context)))
	info.Write(context)
	return hkdfExpand(h, secret, info.Bytes(), length)
}
func deriveSecret(h crypto.Hash, secret []byte, label string, transcriptHash []byte) []byte {
	return hkdfExpandLabel(h, secret, label, transcriptHash, h.Size())
}

