	var curve ecdh.Curve
	switch group {
	case 29:
		curve = ecdh.X25519()
	case 23:
		curve = ecdh.P256()
	case 24:
		curve = ecdh.P384()
	default:
		return nil, fmt.Errorf("unsupported group")
