	ci := &clientHelloInfo{shares: map[uint16][]byte{}}
	if len(body) < 2+32+1 { return nil, fmt.Errorf("short CH") }
	body = body[2:]
	ci.random = append([]byte{}, body[:32]...); body = body[32:]
