		l := int(binary.BigEndian.Uint16(d[:2])); d=d[2:]
		for i:=0;i+1<l && i+1<len(d);i+=2 { ci.sigAlgs = append(ci.sigAlgs, binary.BigEndian.Uint16(d[i:])) }
	}
