		l := int(binary.BigEndian.Uint16(d[:2])); d=d[2:]
		end := 2+l; if end>len(d) { end=len(d) }; d0:=d; _=end
		for len(d0)>=4 {
			g:=binary.BigEndian.Uint16(d0[:2]); kl:=int(binary.BigEndian.Uint16(d0[2:4])); d0=d0[4:]
			if len(d0)<kl { break }
