func (t *tlsState) deriveHandshakeSecrets(shared []byte) {
	h := t.suite.hash
	early := hkdfExtract(h, make([]byte, h.Size()), make([]byte, h.Size()))
	emptyHash := hashBytes(h, nil)
	derived := deriveSecret(h, early, "derived", emptyHash)
	handshakeSecret := hkdfExtract(h, derived, shared)
	t.handshakeSecret = handshakeSecret
	th := t.transcriptHash()
	t.clientHsSecret = deriveSecret(h, handshakeSecret, "c hs traffic", th)
	t.serverHsSecret = deriveSecret(h, handshakeSecret, "s hs traffic", th)
	if t.onKeyLog != nil {
		t.onKeyLog([]string{
			fmt.Sprintf("CLIENT_HANDSHAKE_TRAFFIC_SECRET %x %x", t.clientRandom, t.clientHsSecret),
			fmt.Sprintf("SERVER_HANDSHAKE_TRAFFIC_SECRET %x %x", t.clientRandom, t.serverHsSecret),
		})
	}
}

// Client side, returns client Finished message when server Finished processed.
func (t *tlsState) clientProcess(msg []byte) ([]byte, error) {
	if len(msg) < 4 {
		return nil, fmt.Errorf("short handshake")
	}
	typ := msg[0]
	switch typ {
	case 2: // ServerHello
		// processServerHello adds transcript and derives
		if err := t.processServerHello(msg); err != nil {
			return nil, err
		}
		return nil, nil
	case 8: // EncryptedExtensions
		body := msg[4:]
		if len(body) < 2 {
			return nil, fmt.Errorf("short EE")
		}
		extLen := int(binary.BigEndian.Uint16(body[:2]))
		if len(body) < 2+extLen {
			return nil, fmt.Errorf("short EE ext")
		}
		pe, err := parseExtensions(body[2 : 2+extLen])
		if err != nil {
			return nil, err
		}
		if d, ok := pe.byType[0x39]; ok {
			t.peerTP = append([]byte{}, d...)
		}
		if d, ok := pe.byType[16]; ok && len(d) >= 2 {
			l := int(binary.BigEndian.Uint16(d[:2]))
			d = d[2:]
			if l <= len(d) && len(d) > 0 {
				ll := int(d[0])
				if len(d) >= 1+ll {
					t.selectedAlpn = string(d[1 : 1+ll])
				}
			}
		}
		t.addTranscript(msg)
		return nil, nil
	case 11: // Certificate
		body := msg[4:]
		if len(body) < 1 {
			return nil, fmt.Errorf("short cert")
		}
		body = body[1:] // context
		if len(body) < 3 {
			return nil, fmt.Errorf("short cert list")
		}
		listLen := int(body[0])<<16 | int(body[1])<<8 | int(body[2])
		body = body[3:]
		if len(body) < listLen {
			return nil, fmt.Errorf("short cert list2")
		}
		body = body[:listLen]
		t.serverCerts = nil
		for len(body) >= 3 {
			cl := int(body[0])<<16 | int(body[1])<<8 | int(body[2])
			body = body[3:]
			if len(body) < cl+2 {
				return nil, fmt.Errorf("short cert entry")
			}
			cert := append([]byte{}, body[:cl]...)
			t.serverCerts = append(t.serverCerts, cert)
			body = body[cl:]
			el := int(binary.BigEndian.Uint16(body[:2]))
			body = body[2+el:]
		}
		t.addTranscript(msg)
		return nil, nil
	case 15: // CertificateVerify
		body := msg[4:]
		if len(body) < 4 {
			return nil, fmt.Errorf("short CV")
		}
		alg := binary.BigEndian.Uint16(body[:2])
		sl := int(binary.BigEndian.Uint16(body[2:4]))
		if len(body) < 4+sl {
			return nil, fmt.Errorf("short CV sig")
		}
		sig := body[4 : 4+sl]
		if len(t.serverCerts) == 0 {
			return nil, fmt.Errorf("CV without cert")
		}
		cert, err := x509.ParseCertificate(t.serverCerts[0])
		if err != nil {
			return nil, fmt.Errorf("bad server cert")
		}
		content := cvContent(t.suite, t.transcriptHash())
		if err := verifyCV(cert.PublicKey, alg, content, sig); err != nil {
			return nil, err
		}
		t.addTranscript(msg)
		return nil, nil
	case 20: // Finished
		body := msg[4:]
		expect := finishedVerify(t.serverHsSecret, t.transcriptHash(), t.suite)
		if !hmac.Equal(body, expect) {
			return nil, fmt.Errorf("server Finished verify failed")
		}
		t.addTranscript(msg)
		t.gotServerFinished = true
		t.deriveAppSecrets()
		// build client Finished
		verify := finishedVerify(t.clientHsSecret, t.transcriptHash(), t.suite)
		fmsg := hsMessage(20, verify)
		t.addTranscript(fmsg)
		t.sentClientFinished = true
		t.established = true
		return fmsg, nil
	default:
		// post-handshake ignore
		return nil, nil
	}
}

func (t *tlsState) serverProcessClientHello(msg []byte) (shMsg []byte, hsFlight []byte, err error) {
	ci, err := parseClientHello(msg[4:])
	if err != nil {
		return nil, nil, err
	}
	copy(t.clientRandom[:], ci.random)
	// choose suite
	var chosen *cipherSuite
	for _, pref := range []*cipherSuite{suiteAES128, suiteAES256} {
		for _, s := range ci.suites {
			if s == pref.id {
				chosen = pref
				break
			}
		}
		if chosen != nil {
			break
		}
	}
	if chosen == nil {
		return nil, nil, fmt.Errorf("no cipher suite")
	}
	t.suite = chosen
	// choose group
	var chosenGroup uint16
	var peerShare []byte
	for _, g := range []uint16{29, 23, 24} {
		if share, ok := ci.shares[g]; ok {
			chosenGroup = g
			peerShare = share
			break
		}
	}
	if chosenGroup == 0 {
		return nil, nil, fmt.Errorf("no key share")
	}
	myKey, err := generateECDHE(chosenGroup)
	if err != nil {
		return nil, nil, err
	}
	t.myECDHESingle = myKey
	shared, err := ecdheShared(myKey, peerShare)
	if err != nil {
		return nil, nil, err
	}
	t.peerTP = ci.tp
	t.peerAlpn = ci.alpn
	// transcript CH
	t.addTranscript(msg)
	// Build ServerHello
	rand.Read(t.serverRandom[:])
	var body bytes.Buffer
	u16(&body, 0x0303)
	body.Write(t.serverRandom[:])
	body.WriteByte(0)
	u16(&body, t.suite.id)
	body.WriteByte(0)
	var exts bytes.Buffer
	writeExtension(&exts, 43, []byte{0x03, 0x04})
	{
		var ks bytes.Buffer
		u16(&ks, chosenGroup)
		u16(&ks, uint16(len(myKey.pub)))
		ks.Write(myKey.pub)
		writeExtension(&exts, 51, ks.Bytes())
	}
	u16(&body, uint16(exts.Len()))
	body.Write(exts.Bytes())
	shMsg = hsMessage(2, body.Bytes())
