// ---------- varint ----------
func encodeVarint(v uint64) []byte {
	switch {
	case v < 64:
		return []byte{byte(v)}
	case v < 16384:
		out := make([]byte, 2)
		binary.BigEndian.PutUint16(out, uint16(v)|0x4000)
		return out
	case v < 1073741824:
		out := make([]byte, 4)
		binary.BigEndian.PutUint32(out, uint32(v)|0x80000000)
		return out
	default:
		out := make([]byte, 8)
		binary.BigEndian.PutUint64(out, v|0xC000000000000000)
		return out
	}
}
func decodeVarint(b []byte) (uint64, int, bool) {
	if len(b) == 0 {
		return 0, 0, false
	}
	prefix := b[0] >> 6
	switch prefix {
	case 0:
		return uint64(b[0] & 0x3f), 1, true
	case 1:
		if len(b) < 2 { return 0, 0, false }
		return uint64(binary.BigEndian.Uint16(b[:2]) & 0x3fff), 2, true
	case 2:
		if len(b) < 4 { return 0, 0, false }
		return uint64(binary.BigEndian.Uint32(b[:4]) & 0x3fffffff), 4, true
	default:
		if len(b) < 8 { return 0, 0, false }
		return binary.BigEndian.Uint64(b[:8]) & 0x3fffffffffffffff, 8, true
	}
}
func appendVarint(dst []byte, v uint64) []byte { return append(dst, encodeVarint(v)...) }

