		case 1: tp.maxIdleTimeout=getV()
		case 2: tp.statelessToken=val
		case 3: tp.initialMaxData=getV()
		case 4: tp.initialMaxStreamDataBidiLocal=getV()
		case 5: tp.initialMaxStreamDataBidiRemote=getV()
		case 6: tp.initialMaxStreamDataUni=getV()
		case 7: tp.initialMaxStreamsBidi=getV()
		case 8: tp.initialMaxStreamsUni=getV()
		case 9: tp.ackDelayExponent=getV()
		case 10: tp.maxAckDelay=getV()
		case 13: tp.activeConnIDLimit=getV()
		case 14: tp.initialSourceCID=val
		case 16: tp.maxUDPPayloadSize=getV(); tp.hasMaxUDPPayload=true
