func reconstructPN(largest uint64, hasLargest bool, truncated uint64, pnLen int) uint64 {
	if !hasLargest { return truncated }
	expected := largest + 1
	win := uint64(1) << uint(pnLen*8)
	half := win/2
	mask := ^(win-1)
	candidate := (expected & mask) | truncated
	if candidate <= expected-half && candidate < (1<<62)-win { candidate += win } else if candidate > expected+half && candidate >= win { candidate -= win }
