// ---------- packet receive ----------
func (c *Conn) terminateLocked(err error) {
	if c.closed { return }
	c.closed=true
	if err!=nil { c.closeErr=err; if !c.established { c.handshakeErr=err } }
	close(c.doneCh)
	c.broadcastLocked()
	if c.onClose!=nil { go c.onClose() }
}
func (c *Conn) failLocked(err error) {
	// try to send transport close in app or handshake space if possible
	c.terminateLocked(err)
}

type packetInfo struct {
	space int
	isLong bool
	dcid []byte
	scid []byte
	pn uint64
	payload []byte
	ackEliciting bool
	rawLen int
}

func (c *Conn) processDatagram(data []byte, remote *net.UDPAddr) {
	c.mu.Lock(); defer c.mu.Unlock()
	if c.closed { return }
	c.remote = remote
	c.udpRxDatagrams++; c.udpRxBytes+=uint64(len(data)); c.udpRxIos++
	c.lastRecv=time.Now()
	rem:=data
	for len(rem)>0 {
		if rem[0]&0x80 != 0 {
			// long header
			if len(rem)<5 { return }
			version:=binary.BigEndian.Uint32(rem[1:5])
			if version==0 {
				// version negotiation, ignore
				return
			}
			if version!=1 {
				if c.isServer { c.sendVersionNegotiationLocked(rem, remote) }
				return
			}
			pos:=5
			if pos>=len(rem){return}; dcidLen:=int(rem[pos]); pos++; if len(rem)<pos+dcidLen+1{return}; dcid:=append([]byte{}, rem[pos:pos+dcidLen]...); pos+=dcidLen
			scidLen:=int(rem[pos]); pos++; if len(rem)<pos+scidLen{return}; scid:=append([]byte{}, rem[pos:pos+scidLen]...); pos+=scidLen
			_ = dcid; _ = scid
			typ:=(rem[0]>>4)&0x3
			var space int
			switch typ { case 0: space=0; case 1: return; case 2: space=1; case 3: return }
			if space==0 {
				tokLen,n,ok:=decodeVarint(rem[pos:]); if !ok{return}; pos+=n; if uint64(len(rem))<uint64(pos)+tokLen{return}; pos+=int(tokLen)
			}
			length,n,ok:=decodeVarint(rem[pos:]); if !ok{return}; pos+=n
			packetLen:=pos+int(length)
			if packetLen>len(rem) { return }
			pkt:=append([]byte{}, rem[:packetLen]...)
			c.processPacketLocked(pkt, true, space, pos)
			rem=rem[packetLen:]
		} else {
			pkt:=append([]byte{}, rem...)
			c.processPacketLocked(pkt, false, 2, 1+len(c.ourCID))
			break
		}
		if c.closed { break }
	}
	// after processing, flush
	if !c.closed { c.flushLocked() }
}
func (c *Conn) sendVersionNegotiationLocked(orig []byte, remote *net.UDPAddr) {
	// orig long header parse scid/dcid swapped
	if len(orig)<6 { return }
	pos:=5; dcidLen:=int(orig[pos]); pos++; if len(orig)<pos+dcidLen+1{return}; dcid:=orig[pos:pos+dcidLen]; pos+=dcidLen; scidLen:=int(orig[pos]); pos++; if len(orig)<pos+scidLen{return}; scid:=orig[pos:pos+scidLen]
	var out []byte
	out=append(out, 0x80); out=append(out,0,0,0,0); out=append(out,byte(len(scid))); out=append(out,scid...); out=append(out,byte(len(dcid))); out=append(out,dcid...); out=append(out,0,0,0,1); out=append(out,0x6b,0x33,0x43,0xcf)
	c.writeDatagramLocked(out, remote)
}

func (c *Conn) processPacketLocked(raw []byte, isLong bool, space int, pnOffset int) {
	sp:=c.spaces[space]
	suite:=spaceSuite(c, space)
	// determine pn and payload
	if len(raw) < pnOffset+1 { return }
	var pn uint64
	var plain []byte
	var aad []byte
	pnLen:=0
	if c.noProtection {
		pnLen=int(raw[0]&0x03)+1
		if len(raw)<pnOffset+pnLen { return }
		for i:=0;i<pnLen;i++ { pn = (pn<<8)|uint64(raw[pnOffset+i]) }
		plain=append([]byte{}, raw[pnOffset+pnLen:]...)
		pn = reconstructPN(sp.largestRecv, sp.hasLargest, pn, pnLen)
	} else {
		keys:=sp.rxKeys
		if keys==nil { return }
		// key phase for app
		if space==2 {
			phase := 0
			// phase bit not known until unmask first byte; handle below
			_ = phase
		}
		if len(raw) < pnOffset+4+16 { return }
		sample:=raw[pnOffset+4:pnOffset+4+16]
		// For app space, keys may need phase switching: try current keys first, phase determination after unmask uses current rx key's hp (hp same across phases? hp key changes with secret update)
		// We'll attempt with current keys; if HP/AEAD fail and app, try deriving next phase and retry once.
		type attempt struct{keys *keyMaterial; phase int}
		attempts:=[]attempt{{keys, sp.rxPhase}}
		if space==2 && sp.rxSecret!=nil {
			// compute candidate next secret keys
			nextSecret:=hkdfExpandLabel(suite.hash, sp.rxSecret, "quic ku", nil, suite.hash.Size())
			attempts=append(attempts, attempt{keysFromSecret(suite.hash, suite, nextSecret), sp.rxPhase^1})
		}
		var lastErr error
		success:=false
		for _, at := range attempts {
			mask, err:=hpMask(at.keys.hp, sample, suite); if err!=nil{lastErr=err; continue}
			hdr:=append([]byte{}, raw[:pnOffset+4]...)
			if isLong { hdr[0] ^= mask[0]&0x0f } else { hdr[0] ^= mask[0]&0x1f }
			pl:=int(hdr[0]&0x03)+1
			if space==2 {
				ph:=0; if hdr[0]&0x04!=0 { ph=1 }
				if ph!=at.phase && !(len(attempts)>1 && at.phase==sp.rxPhase) {
					// If phase doesn't match this attempt's phase, skip unless it's current attempt which we may still try (should match)
					if ph!=at.phase { continue }
				}
			}
			if len(raw)<pnOffset+pl { continue }
			for i:=0;i<pl;i++ { hdr[pnOffset+i] ^= mask[1+i] }
			var trunc uint64; for i:=0;i<pl;i++ { trunc=(trunc<<8)|uint64(hdr[pnOffset+i]) }
			fullPN:=reconstructPN(sp.largestRecv, sp.hasLargest, trunc, pl)
			aadCopy:=append([]byte{}, hdr[:pnOffset+pl]...)
			pt, err:=aeadOpen(at.keys, suite, fullPN, aadCopy, raw[pnOffset+pl:])
			if err!=nil { lastErr=err; continue }
			// success, commit phase switch if needed
			if space==2 && at.phase!=sp.rxPhase {
				sp.rxSecret = hkdfExpandLabel(suite.hash, sp.rxSecret, "quic ku", nil, suite.hash.Size())
				sp.rxKeys = keysFromSecret(suite.hash, suite, sp.rxSecret)
				sp.rxPhase = at.phase
			}
			pnLen=pl; pn=fullPN; plain=pt; aad=aadCopy; success=true; break
		}
		_ = lastErr
		if !success { return }
		_ = aad
	}
	if c.cfg.Qlog!=nil { c.cfg.Qlog.packetEvent(false, packetTypeName(space,isLong), pn, len(raw), c.qlogGroup) }
	// duplicate?
	if prev, ok:=sp.recvPNs[pn]; ok && prev { return }
	sp.recvPNs[pn]=true
	if !sp.hasLargest || pn>sp.largestRecv { sp.largestRecv=pn; sp.hasLargest=true; sp.largestRecvTime=time.Now() }
	// update remote CID from long header scid if present
	if isLong {
		// parse scid to update destCID for server/client responses: peer's source cid is our destination
		pos:=5; if pos < len(raw) { dcidLen:=int(raw[pos]); pos+=1+dcidLen; if pos < len(raw) { scidLen:=int(raw[pos]); pos++; if len(raw)>=pos+scidLen { scid:=append([]byte{}, raw[pos:pos+scidLen]...); if len(scid)>0 { c.destCID=scid } } } }
	}
	ackEliciting:=c.processFramesLocked(space, plain)
	if ackEliciting {
		if !sp.ackNeeded { sp.ackFirstTime=time.Now() }
		sp.ackNeeded=true; sp.ackEliciting++
	}
}

type frameReader struct { b []byte; pos int }
func (r *frameReader) varint() (uint64,bool) { v,n,ok:=decodeVarint(r.b[r.pos:]); if ok{r.pos+=n}; return v,ok }
func (r *frameReader) bytes(n int) []byte { if len(r.b)<r.pos+n{return nil}; v:=r.b[r.pos:r.pos+n]; r.pos+=n; return v }

func (c *Conn) processFramesLocked(space int, payload []byte) bool {
	r:=&frameReader{b:payload}
	ackEliciting:=false
	sp:=c.spaces[space]
	for r.pos < len(r.b) {
		typ, ok:=r.varint(); if !ok{break}
		switch typ {
		case 0x00: // padding
			continue
		case 0x01:
			c.frameRx.inc("PING"); ackEliciting=true
		case 0x02, 0x03:
			c.frameRx.inc("ACK")
			largest,ok1:=r.varint(); delay,ok2:=r.varint(); rangeCount,ok3:=r.varint(); firstRange,ok4:=r.varint(); if !ok1||!ok2||!ok3||!ok4{return ackEliciting}
			var acked []uint64
			curLargest:=largest; curRange:=firstRange
			for i:=uint64(0);;i++ {
				for pn:=curLargest-curRange; ; pn++ {
					acked=append(acked,pn); if pn==curLargest{break}
				}
				if i>=rangeCount { break }
				gap,ok1:=r.varint(); rng,ok2:=r.varint(); if !ok1||!ok2{break}
				// next largest = (curLargest - curRange) - gap -2
				smallest:=curLargest-curRange
				if smallest < gap+2 { break }
				curLargest = smallest - gap - 2; curRange=rng
			}
			if typ==0x03 { r.varint(); r.varint(); r.varint() }
			c.handleAckLocked(space, acked, delay)
		case 0x04: // reset stream
			c.frameRx.inc("RESET_STREAM"); ackEliciting=true
			sid,ok1:=r.varint(); code,ok2:=r.varint(); _,ok3:=r.varint(); if !ok1||!ok2||!ok3{return ackEliciting}
			s:=c.newStreamLocked(sid); if s.recv!=nil { cc:=code; s.recv.resetCode=&cc }
			c.broadcastLocked()
		case 0x05:
			c.frameRx.inc("STOP_SENDING"); ackEliciting=true
			sid,ok1:=r.varint(); _,ok2:=r.varint(); if !ok1||!ok2{return ackEliciting}
			s:=c.streams[sid]; if s!=nil && s.send!=nil { s.send.pending=nil; c.broadcastLocked() }
		case 0x06:
			c.frameRx.inc("CRYPTO"); ackEliciting=true
			off,ok1:=r.varint(); ln,ok2:=r.varint(); if !ok1||!ok2{return ackEliciting}
			data:=r.bytes(int(ln)); if data==nil{return ackEliciting}
			sp.cryptoRecv.insert(dataSeg{off:off, data:append([]byte{},data...)})
			c.processCryptoLocked(space)
		case 0x07:
			c.frameRx.inc("NEW_TOKEN"); ackEliciting=true
			ln,ok:=r.varint(); if !ok{return ackEliciting}; r.bytes(int(ln))
		case 0x08,0x09,0x0a,0x0b,0x0c,0x0d,0x0e,0x0f:
			c.frameRx.inc("STREAM"); ackEliciting=true
			sid,ok:=r.varint(); if !ok{return ackEliciting}
			var off uint64; if typ&0x04!=0 { off,_=r.varint() }
			var data []byte
			if typ&0x02!=0 { ln,_:=r.varint(); data=r.bytes(int(ln)); if data==nil{return ackEliciting} } else { data=r.b[r.pos:]; r.pos=len(r.b) }
			fin:=typ&0x01!=0
			s:=c.newStreamLocked(sid)
			if s.recv!=nil {
				s.recv.insert(dataSeg{off:off, data:append([]byte{},data...), fin:fin})
				if fin && len(data)==0 {
					// register fin at offset
					o:=off; if s.recv.finOff==nil { s.recv.finOff=&o }
				}
				// flow checks ignored for robustness
				c.broadcastLocked()
			}
		case 0x10:
			c.frameRx.inc("MAX_DATA"); ackEliciting=true
			v,_:=r.varint(); if c.peerTP!=nil { /* peer increased our conn limit: store in a field via peerTP mutation */ c.peerTP.initialMaxData=v }; c.broadcastLocked()
		case 0x11:
			c.frameRx.inc("MAX_STREAM_DATA"); ackEliciting=true
			sid,_:=r.varint(); v,_:=r.varint(); if s:=c.streams[sid]; s!=nil && s.send!=nil { if v>s.sendWindow {s.sendWindow=v}; }; c.broadcastLocked()
		case 0x12:
			c.frameRx.inc("MAX_STREAMS_BIDI"); ackEliciting=true
			v,_:=r.varint(); if v>c.peerMaxStreamsBidi{c.peerMaxStreamsBidi=v}; c.broadcastLocked()
		case 0x13:
			c.frameRx.inc("MAX_STREAMS_UNI"); ackEliciting=true
			v,_:=r.varint(); if v>c.peerMaxStreamsUni{c.peerMaxStreamsUni=v}; c.broadcastLocked()
		case 0x14: c.frameRx.inc("DATA_BLOCKED"); ackEliciting=true; r.varint()
		case 0x15: c.frameRx.inc("STREAM_DATA_BLOCKED"); ackEliciting=true; r.varint(); r.varint()
		case 0x16: c.frameRx.inc("STREAMS_BLOCKED_BIDI"); ackEliciting=true; r.varint()
		case 0x17: c.frameRx.inc("STREAMS_BLOCKED_UNI"); ackEliciting=true; r.varint()
		case 0x18:
			c.frameRx.inc("NEW_CONNECTION_ID"); ackEliciting=true
			seq,_:=r.varint(); retire,_:=r.varint(); if r.pos>=len(r.b){return ackEliciting}; ln:=int(r.b[r.pos]); r.pos++; cid:=r.bytes(ln); token:=r.bytes(16); _=token
			if cid!=nil { c.peerCIDs[seq]=append([]byte{},cid...)
				if int64(retire)>c.peerRetiredDestSeq {
					// switch destination to smallest seq >= retire if available
					for sq:=retire; ; sq++ { if cc,ok:=c.peerCIDs[sq]; ok { c.destCID=append([]byte{},cc...); break }; if sq>retire+16{break} }
					c.peerRetiredDestSeq=int64(retire)
				}
			}
		case 0x19:
			c.frameRx.inc("RETIRE_CONNECTION_ID"); ackEliciting=true
			seq,_:=r.varint()
			if seq==c.currentSourceSeq {
				// switch to next issued
				for sq:=seq+1;;sq++ { if cid,ok:=c.issuedCIDs[sq]; ok { c.ourCID=append([]byte{},cid...); c.currentSourceSeq=sq; break }; if sq>seq+16{break} }
			}
		case 0x1a:
			c.frameRx.inc("PATH_CHALLENGE"); ackEliciting=true; d:=r.bytes(8); if d!=nil{c.pathResponses=append(c.pathResponses,append([]byte{},d...))}
		case 0x1b:
			c.frameRx.inc("PATH_RESPONSE"); ackEliciting=true; r.bytes(8)
		case 0x1c:
			c.frameRx.inc("CONNECTION_CLOSE")
			code,_:=r.varint(); r.varint(); ln,_:=r.varint(); reason:=r.bytes(int(ln)); _=code
			err:=fmt.Errorf("closed by peer: %s (code %d)", string(reason), code)
			c.terminateLocked(err); return ackEliciting
		case 0x1d:
			c.frameRx.inc("CONNECTION_CLOSE")
			code,_:=r.varint(); ln,_:=r.varint(); reason:=r.bytes(int(ln))
			err:=fmt.Errorf("closed by peer: %s (code %d)", string(reason), code)
			c.terminateLocked(err); return ackEliciting
		case 0x1e:
			c.frameRx.inc("HANDSHAKE_DONE"); ackEliciting=true
		case 0x1f:
			c.frameRx.inc("IMMEDIATE_ACK"); // draft immediate ack has no fields
			// force ack of this packet will be handled due ackEliciting? This frame itself in a packet makes it ack-eliciting? treat as ack-eliciting
			ackEliciting=true
			sp.ackNeeded=true; sp.ackEliciting=2
		case 0xaf:
			c.frameRx.inc("ACK_FREQUENCY"); ackEliciting=true
			// seq, threshold, max ack delay, reordering threshold
			r.varint(); r.varint(); mad,ok:=r.varint(); if ok && mad>0 && mad<10000 { c.ackDelayMs=mad }
			r.varint()
		case 0x30,0x31:
			c.frameRx.inc("DATAGRAM"); ackEliciting=true
			if typ&1!=0 { ln,_:=r.varint(); r.bytes(int(ln)) } else { r.pos=len(r.b) }
		default:
			// Unknown frame: protocol error
			err:=fmt.Errorf("received a frame that was badly formatted: invalid frame ID")
			c.terminateLocked(err); return ackEliciting
		}
	}
	_ = sp
	return ackEliciting
}

func (c *Conn) handleAckLocked(space int, acked []uint64, delayRaw uint64) {
	sp:=c.spaces[space]
	exp:=uint64(3); if c.peerTP!=nil { exp=c.peerTP.ackDelayExponent }
	ackDelay:=time.Duration(delayRaw<<exp)*time.Microsecond
	for _,pn:=range acked {
		pkt, ok:=sp.sent[pn]; if !ok{continue}
		delete(sp.sent,pn)
		for _,fr:=range pkt.frames {
			switch fr.kind {
			case 0: sp.cryptoSend.markAcked(fr.seg)
			case 1: if fr.stream!=nil && fr.stream.send!=nil { fr.stream.send.markAcked(fr.seg) }
			}
		}
		if !sp.hasLargestAcked || pn>sp.largestAcked { sp.largestAcked=pn; sp.hasLargestAcked=true
			if pkt.ackEliciting {
				sample:=time.Since(pkt.sent)-ackDelay; if sample<0{sample=time.Since(pkt.sent)}
				if !c.rttSet { c.rtt=sample; c.rttSet=true } else { c.rtt = time.Duration(float64(c.rtt)*0.875+float64(sample)*0.125) }
			}
		}
		// cwnd growth approx
		if pkt.ackEliciting && c.cwnd<4*1024*1024 {
			inc:=pkt.size*1200/maxInt(c.cwnd,1); if inc<1{inc=1}; c.cwnd+=inc; if c.cwnd>4*1024*1024{c.cwnd=4*1024*1024}
		}
	}
	c.broadcastLocked()
}
func maxInt(a,b int) int { if a>b{return a}; return b }

func (c *Conn) processCryptoLocked(space int) {
	sp:=c.spaces[space]
	if len(sp.cryptoRecv.ready)>0 {
		sp.cryptoProcessed=append(sp.cryptoProcessed, sp.cryptoRecv.ready...)
		sp.cryptoRecv.ready=nil
	}
	for len(sp.cryptoProcessed)>=4 {
		ln:=int(sp.cryptoProcessed[1])<<16|int(sp.cryptoProcessed[2])<<8|int(sp.cryptoProcessed[3])
		if len(sp.cryptoProcessed)<4+ln { return }
		msg:=append([]byte{}, sp.cryptoProcessed[:4+ln]...)
		sp.cryptoProcessed=sp.cryptoProcessed[4+ln:]
		if c.isServer {
			if price==0 {
				if c.serverFlightSent { continue }
				sh, flight, err:=c.tls.serverProcessClientHello(msg); if err!=nil { c.failLocked(err); return }
				// peer TP
				if c.tls.peerTP!=nil { if tp,err:=parseTransportParams(c.tls.peerTP); err==nil { c.applyPeerTP(tp) } }
				c.setHandshakeKeys(); c.setAppKeys()
				c.spaces[0].cryptoSend.appendData(sh)
				c.spaces[1].cryptoSend.appendData(flight)
				c.serverFlightSent=true
			} else if price==1 {
				if err:=c.tls.serverProcessClientFinished(msg); err!=nil { c.failLocked(err); return }
				if c.tls.established { c.signalEstablishedLocked() }
			} else {
				// app crypto ignored
			}
		} else {
			if price==2 { continue }
			wasEst:=c.established
			finMsg, err:=c.tls.clientProcess(msg); if err!=nil { c.failLocked(err); return }
			if msg[0]==2 { c.setHandshakeKeys() }
			if c.tls.peerTP!=nil && c.peerTP==nil { if tp,err:=parseTransportParams(c.tls.peerTP); err==nil { c.applyPeerTP(tp) } }
			if finMsg!=nil {
				c.setAppKeys()
				c.spaces[1].cryptoSend.appendData(finMsg)
				c.needHandshakeDone=true
				c.signalEstablishedLocked()
			}
			_ = wasEst
		}
	}
}

