// ---------- timers / loss ----------
func (c *Conn) declareLostLocked(space int, pn uint64) {
	sp:=c.spaces[space]
	pkt, ok:=sp.sent[pn]; if !ok{return}
	delete(sp.sent,pn)
	if pkt.ackEliciting { c.lostPackets++; c.lostBytes+=uint64(pkt.size); c.congestionEvents++; if c.cwnd>24000{c.cwnd/=2} else {c.cwnd=12000} }
	for _,fr:=range pkt.frames {
		switch fr.kind {
		case 0: sp.cryptoSend.pending=addPendingSeg(sp.cryptoSend.pending, fr.seg)
		case 1: if fr.stream!=nil && fr.stream.send!=nil { fr.stream.send.pending=addPendingSeg(fr.stream.send.pending, fr.seg) }
		case 2:
			switch fr.control {
			case "handshake_done": if !c.handshakeDoneSent { c.needHandshakeDone=true }
			case "max_data": c.needMaxData=true
			case "max_stream_data": if fr.stream!=nil{fr.stream.needMaxStreamDataFlag=true}
			case "max_streams_bidi": c.needMaxStreamsBidi=true
			case "max_streams_uni": c.needMaxStreamsUni=true
			}
		}
	}
	c.broadcastLocked()
}
func (c *Conn) timerLoop() {
	ticker:=time.NewTicker(5*time.Millisecond); defer ticker.Stop()
	for {
		select { case <-c.doneCh: return; case <-ticker.C: }
		c.mu.Lock()
		if c.closed { c.mu.Unlock(); return }
		// loss based on ack
		now:=time.Now()
		for _,sp:=range c.spaces {
			if sp.hasLargestAcked {
				var lost []uint64
				for pn,pkt:=range sp.sent { if pkt.ackEliciting && pn+3<=sp.largestAcked && now.Sub(pkt.sent)>10*time.Millisecond { lost=append(lost,pn) } }
				for _,pn:=range lost { c.declareLostLocked(sp.id,pn) }
			}
			// PTO: oldest unacked ack-eliciting
			var oldest *sentPacket; var oldestPN uint64
			for pn,pkt:=range sp.sent { if pkt.ackEliciting && (oldest==nil || pkt.sent.Before(oldest.sent)) { oldest=pkt; oldestPN=pn } }
			if oldest!=nil {
				pto:=300*time.Millisecond; if c.rttSet && c.rtt*3>pto { pto=c.rtt*3 }
				if now.Sub(oldest.sent)>pto {
					c.declareLostLocked(sp.id, oldestPN)
