		shouldFlush:=false
		for _,sp:=range c.spaces { if c.ackDueLocked(sp){shouldFlush=true} }
		if shouldFlush || c.hasPendingLocked() || c.probesToSend>0 { c.flushLocked() }
		c.mu.Unlock()
	}
}

// ---------- stream API ----------
func (c *Conn) OpenStream(bidi bool) (*QStream, error) {
	c.mu.Lock(); defer c.mu.Unlock()
	for {
		if c.closed {
			if c.closeErr!=nil { return nil, c.closeErr }
			return nil, fmt.Errorf("connection lost: closed")
		}
		if !c.established { // wait
			ch:=c.notifyCh; c.mu.Unlock(); c.waitNotify(ch); c.mu.Lock(); continue
		}
