		if bidi { idx=c.nextBidiIdx; limit=c.peerMaxStreamsBidi; typBit=0 } else { idx=c.nextUniIdx; limit=c.peerMaxStreamsUni; typBit=2 }
		if limit>0 && idx>=limit {
			ch:=c.notifyCh; c.mu.Unlock(); c.waitNotify(ch); c.mu.Lock(); continue
		}
		var initBit uint64; if c.isServer { initBit=1 }
		id:=idx<<2|initBit|typBit
