// ---------- client dial ----------
func DialQUIC(udp *net.UDPConn, remote *net.UDPAddr, serverName string, cfg QUICConfig) (*Conn, error) {
	c:=newConn(cfg,false)
	c.udp=udp; c.remote=remote; c.local=nil
	if la,ok:=udp.LocalAddr().(*net.UDPAddr); ok { c.local=la }
	c.ourCID=randomCID(); dest:=randomCID(); c.destCID=dest; c.initialDCID=append([]byte{},dest...); c.issuedCIDs[0]=append([]byte{},c.ourCID...); c.qlogGroup=fmt.Sprintf("%x",dest)
	c.tls=&tlsState{isServer:false, serverName:serverName, offeredAlpn:cfg.ALPN}
	if cfg.KeyLog!=nil { kl:=cfg.KeyLog; c.tls.onKeyLog=func(lines []string){ kl.writeLines(lines)} }
	c.setupTransportParams()
	c.setInitialKeys()
	ch, err:=c.tls.buildClientHello(); if err!=nil{return nil,err}
	c.spaces[0].cryptoSend.appendData(ch)
	c.onClose=func(){ udp.Close() }
	// read loop
	go func(){
		buf:=make([]byte,65536)
		for {
			n, addr, err:=udp.ReadFromUDP(buf); if err!=nil{return}
			data:=append([]byte{},buf[:n]...); _=addr
			c.processDatagram(data, remote)
		}
	}()
	go c.timerLoop()
	c.mu.Lock(); c.flushLocked(); c.mu.Unlock()
	// wait 30 sec
	err=c.WaitEstablished(30*time.Second)
	if err!=nil {
		// distinguish timed out vs other: Wait returns "timed out" specifically for timeout
		c.mu.Lock(); c.terminateLocked(err); c.mu.Unlock()
		udp.Close()
		return nil, err
	}
	return c,nil
}

// ---------- server endpoint ----------
type ServerEndpoint struct {
	udp *net.UDPConn
	cfg QUICConfig
	mu sync.Mutex
	conns map[string]*Conn // keyed by CID bytes (string)
	byRemote map[string]*Conn
	incoming chan *Conn
	closed bool
}
func NewServerEndpoint(udp *net.UDPConn, cfg QUICConfig) *ServerEndpoint {
	e:=&ServerEndpoint{udp:udp, cfg:cfg, conns:map[string]*Conn{}, byRemote:map[string]*Conn{}, incoming:make(chan *Conn,128)}
	go e.readLoop()
	return e
}
func (e *ServerEndpoint) AcceptConn() (*Conn, error) {
	conn, ok:=<-e.incoming
	if !ok { return nil, fmt.Errorf("endpoint closed") }
	return conn,nil
}
func (e *ServerEndpoint) registerConnLocked(c *Conn) {
	e.conns[string(c.ourCID)]=c
	e.conns[string(c.initialDCID)]=c
	for _,cid:=range c.issuedCIDs { e.conns[string(cid)]=c }
	if c.remote!=nil { e.byRemote[c.remote.String()] = c }
}
func (e *ServerEndpoint) readLoop() {
	buf:=make([]byte,65536)
	for {
		n, remote, err:=e.udp.ReadFromUDP(buf); if err!=nil{return}
		data:=append([]byte{},buf[:n]...)
		e.handleDatagram(data, remote)
	}
}
func (e *ServerEndpoint) handleDatagram(data []byte, remote *net.UDPAddr) {
	if len(data)==0 { return }
	// version negotiation handling for unsupported long version before routing
	var dcid, scid []byte; var isLong bool; var typ byte; var version uint32
	if data[0]&0x80!=0 {
		isLong=true
		if len(data)<5{return}; version=binary.BigEndian.Uint32(data[1:5])
		pos:=5; if pos>=len(data){return}; dl:=int(data[pos]); pos++; if len(data)<pos+dl+1{return}; dcid=append([]byte{}, data[pos:pos+dl]...); pos+=dl; sl:=int(data[pos]); pos++; if len(data)<pos+sl{return}; scid=append([]byte{}, data[pos:pos+sl]...); typ=(data[0]>>4)&0x3
		if version==0 { return }
		if version!=1 {
