			tmp:=&Conn{ frameTx:newFrameStats(), frameRx:newFrameStats(), notifyCh:make(chan struct{}), doneCh:make(chan struct{}) }
			tmp.sendFunc=func(b []byte, r *net.UDPAddr) error { _,err:=e.udp.WriteToUDP(b,r); return err }
