		for _,cc:=range e.conns { if cc.remote!=nil && cc.remote.String()==remote.String() { conn=cc; ok=true; break } }
	}
	if !ok {
		if !isLong || typ!=0 { e.mu.Unlock(); return }
		// new connection
		conn = newConn(e.cfg, true)
		conn.remote=remote
		if la,ok2:=e.udp.LocalAddr().(*net.UDPAddr); ok2 { conn.local=la }
		conn.sendFunc=func(b []byte, r *net.UDPAddr) error { _,err:=e.udp.WriteToUDP(b,r); return err }
		conn.ourCID=randomCID(); conn.issuedCIDs[0]=append([]byte{}, conn.ourCID...)
		conn.destCID=append([]byte{}, scid...); conn.initialDCID=append([]byte{}, dcid...); conn.qlogGroup=fmt.Sprintf("%x",dcid)
		conn.tls=&tlsState{isServer:true, signer:e.cfg.Signer, certChain:e.cfg.CertChain}
		if e.cfg.KeyLog!=nil { kl:=e.cfg.KeyLog; conn.tls.onKeyLog=func(lines []string){ kl.writeLines(lines)} }
		conn.setupTransportParams()
		conn.setInitialKeys()
		conn.onClose=func(){
			e.mu.Lock(); for k,v:=range e.conns { if v==conn { delete(e.conns,k)} }; e.mu.Unlock()
		}
		e.registerConnLocked(conn)
		// incoming queue
		select { case e.incoming<-conn: default: go func(){e.incoming<-conn}() }
		go conn.timerLoop()
	}
	e.mu.Unlock()
	conn.processDatagram(data, remote)
	// register any issued CIDs now known
	e.mu.Lock(); e.registerConnLocked(conn); e.mu.Unlock()
}
