package main

import (
	"encoding/binary"
	"encoding/json"
	"fmt"
	"io"
	"math"
	"net"
	"os"
	"sort"
	"strconv"
	"strings"
	"sync"
	"sync/atomic"
	"syscall"
	"time"
)

// ---------- socket creation ----------
func resolveUDPAddrFromString(s string) (*net.UDPAddr, error) {
	// s was validated as socket address
	return net.ResolveUDPAddr("udp", s)
}
func createSocket(addr *net.UDPAddr, sendSize, recvSize uint64) (*net.UDPConn, error) {
	network := "udp"
	if addr.IP != nil {
		if addr.IP.To4() != nil { network = "udp4" } else { network = "udp6" }
	}
	conn, err := net.ListenUDP(network, addr)
	if err != nil {
		return nil, err
	}
	// set buffers after bind, warn if actual < desired, in order send/recv
	setBuf := func(send bool, desired uint64) {
		raw, err := conn.SyscallConn()
		if err != nil { return }
		var actual int
		var setErr error
		raw.Control(func(fd uintptr) {
			opt := syscall.SO_SNDBUF
			if !send { opt = syscall.SO_RCVBUF }
			d := desired
			if d > 2147483647 { d = 2147483647 }
			// syscall on linux
			_ = syscall.SetsockoptInt(int(fd), syscall.SOL_SOCKET, opt, int(d))
			actual, setErr = syscall.GetsockoptInt(int(fd), syscall.SOL_SOCKET, opt)
		})
		_ = setErr
		if uint64(actual) < desired {
			if send {
				logWarn("perf", fmt.Sprintf("Unable to set desired send buffer size. Desired: %d, Actual: %d", desired, actual))
			} else {
				logWarn("perf", fmt.Sprintf("Unable to set desired recv buffer size. Desired: %d, Actual: %d", desired, actual))
			}
		}
	}
	setBuf(true, sendSize)
	setBuf(false, recvSize)
	return conn, nil
}
func udpAddrString(a *net.UDPAddr) string {
	return a.String()
}
func commonToQUIC(c CommonOpts) QUICConfigCommon {
	return QUICConfigCommon{SendBufferSize:c.SendBufferSize, RecvBufferSize:c.RecvBufferSize, InitialMtu:c.InitialMtu, MaxUdpPayloadSize:c.MaxUdpPayloadSize, StreamReceiveWindow:c.StreamReceiveWindow, ReceiveWindow:c.ReceiveWindow, SendWindow:c.SendWindow, InitialRtt:c.InitialRtt, AckFrequency:c.AckFrequency, NoProtection:c.NoProtection, Congestion:c.Congestion}
}
func checkMaxUDP(v uint16) error {
	if v < 1200 || v > 65527 {
		return fmt.Errorf("value exceeds supported bounds")
	}
	return nil
}

// ---------- stats ----------
type streamRecord struct {
	uploadID uint64
	downloadID uint64
	hasUploadID bool
	hasDownloadID bool
	start time.Time
	uploadDur time.Duration
	downloadDur time.Duration
	fbl time.Duration
	uploadBytes uint64
	downloadBytes uint64
	uploadDone bool
	downloadDone bool
}
type jsonStream struct {
	ID uint64 `json:"id"`
	Start float64 `json:"start"`
	End float64 `json:"end"`
	Seconds float64 `json:"seconds"`
	Bytes uint64 `json:"bytes"`
	BitsPerSecond float64 `json:"bits_per_second"`
	Sender bool `json:"sender"`
}
type jsonInterval struct {
	Streams []jsonStream `json:"streams"`
	Sum jsonStream `json:"sum"`
}
type jsonEvent struct {
	id uint64
	bytes uint64
	sender bool
	at time.Duration
}
type statsCollector struct {
	mu sync.Mutex
	start time.Time
	records []*streamRecord
	uniRecords map[uint64]*streamRecord
	numRequests uint64
	events []jsonEvent
	firstEventAt *time.Duration
	intervals []jsonInterval
	lastIntervalEnd float64
	jsonEnabled bool
	uploadSize uint64
	downloadSize uint64
}
func newStatsCollector(jsonEnabled bool, up, down uint64) *statsCollector {
	return &statsCollector{start: time.Now(), uniRecords: map[uint64]*streamRecord{}, jsonEnabled: jsonEnabled, uploadSize:up, downloadSize:down, intervals: []jsonInterval{}}
}
func (s *statsCollector) newRecord() *streamRecord {
	r:=&streamRecord{start: time.Now()}
	s.mu.Lock(); s.records=append(s.records,r); s.mu.Unlock(); return r
}
func (s *statsCollector) getUniRecord(idx uint64) *streamRecord {
	s.mu.Lock(); defer s.mu.Unlock()
	if r,ok:=s.uniRecords[idx]; ok { return r }
	r:=&streamRecord{start: time.Now()}
	s.uniRecords[idx]=r; s.records=append(s.records,r); return r
}
func (s *statsCollector) addEventLocked(id uint64, bytes uint64, sender bool) {
	if !s.jsonEnabled { return }
	at:=time.Since(s.start)
	if s.firstEventAt==nil { v:=at; s.firstEventAt=&v }
	s.events=append(s.events, jsonEvent{id:id, bytes:bytes, sender:sender, at:at})
}
func (s *statsCollector) recordUpload(r *streamRecord, streamID uint64, dur time.Duration, bytes uint64) {
	s.mu.Lock(); defer s.mu.Unlock()
	r.uploadID=streamID; r.hasUploadID=true; r.uploadDur=dur; r.uploadBytes=bytes; r.uploadDone=true
	s.addEventLocked(streamID, bytes, true)
}
func (s *statsCollector) recordDownload(r *streamRecord, streamID uint64, dlDur, fbl time.Duration, bytes uint64) {
	s.mu.Lock(); defer s.mu.Unlock()
	r.downloadID=streamID; r.hasDownloadID=true; r.downloadDur=dlDur; r.fbl=fbl; r.downloadBytes=bytes; r.downloadDone=true
	s.numRequests++
	s.addEventLocked(streamID, bytes, false)
}
func formatDur2(d time.Duration) string {
	if d<=0 { return "0.00ns" }
	ns:=d.Nanoseconds()
	if ns < 1000 { return fmt.Sprintf("%d.00ns", ns) }
	if ns < 1000000 { return fmt.Sprintf("%.2fµs", float64(ns)/1000.0) }
	if ns < 1000000000 { return fmt.Sprintf("%.2fms", float64(ns)/1e6) }
	return fmt.Sprintf("%.2fs", float64(ns)/1e9)
}
func percentileFloat(vals []float64, p int) float64 {
	if len(vals)==0 { return 0 }
	sorted:=append([]float64{}, vals...); sort.Float64s(sorted)
	if p<=0 { return sorted[0] }
	if p>=100 { return sorted[len(sorted)-1] }
	idx:=int(math.Ceil(float64(p)/100.0*float64(len(sorted))))-1
	if idx<0{idx=0}; if idx>=len(sorted){idx=len(sorted)-1}
	return sorted[idx]
}
func percentileDur(vals []time.Duration, p int) time.Duration {
	f:=make([]float64,len(vals)); for i,v:=range vals{f[i]=float64(v)}
	return time.Duration(percentileFloat(f,p))
}
func avgDur(vals []time.Duration) time.Duration {
	if len(vals)==0{return 0}; var sum int64; for _,v:=range vals{sum+=v.Nanoseconds()}; return time.Duration(sum/int64(len(vals)))
}
func avgFloat(vals []float64) float64 { if len(vals)==0{return 0}; var s float64; for _,v:=range vals{s+=v}; return s/float64(len(vals)) }
func thrut(bytes uint64, d time.Duration) float64 {
	if bytes==0 { return 0 }
	if d<=0 { return 147573952589676.41 }
	return float64(bytes)*8.0/d.Seconds()/1e6
}
func (s *statsCollector) snapshot() (uint64, time.Duration, []*streamRecord) {
	s.mu.Lock(); defer s.mu.Unlock()
	recs:=append([]*streamRecord{}, s.records...)
	// copy records to avoid race on fields
	copied:=make([]*streamRecord,len(recs)); for i,r:=range recs{ c:=*r; copied[i]=&c }
	return s.numRequests, time.Since(s.start), copied
}
func (s *statsCollector) printStats() {
	count, elapsed, recs := s.snapshot()
	var upD, downD, fbls []time.Duration
	var upT, downT []float64
	for _,r:=range recs {
		upD=append(upD,r.uploadDur); downD=append(downD,r.downloadDur); fbls=append(fbls,r.fbl)
		upT=append(upT, thrut(r.uploadBytes, r.uploadDur)); downT=append(downT, thrut(r.downloadBytes, r.downloadDur))
	}
	rps:=0.0; if elapsed.Seconds()>0 { rps=float64(count)/elapsed.Seconds() }
	var b strings.Builder
	b.WriteString("Overall stats:\n")
	b.WriteString(fmt.Sprintf("RPS: %.2f (%d requests in %.2fs)\n", rps, count, elapsed.Seconds()))
	b.WriteString("\nStream metrics:\n\n")
	b.WriteString("      │ Upload Duration │ Download Duration | FBL        | Upload Throughput | Download Throughput\n")
	b.WriteString("──────┼─────────────────┼───────────────────┼────────────┼───────────────────┼────────────────────\n")
	labels:=[]string{"AVG","P0","P10","P50","P90","P100"}
	for _,lab:=range labels {
		var ud, dd, fb time.Duration; var ut, dt float64
		if lab=="AVG" { ud=avgDur(upD); dd=avgDur(downD); fb=avgDur(fbls); ut=avgFloat(upT); dt=avgFloat(downT) } else {
			var p int; fmt.Sscanf(lab,"P%d",&p)
			ud=percentileDur(upD,p); dd=percentileDur(downD,p); fb=percentileDur(fbls,p); ut=percentileFloat(upT,p); dt=percentileFloat(downT,p)
		}
		b.WriteString(fmt.Sprintf(" %-5s│ %15s │ %17s │ %10s │ %17s │ %18s\n", lab, formatDur2(ud), formatDur2(dd), formatDur2(fb), fmt.Sprintf("%.2f Mb/s",ut), fmt.Sprintf("%.2f Mb/s",dt)))
	}
	b.WriteString("\n")
	printStdout(b.String())
	// json interval generation at same tick
	if s.jsonEnabled {
		s.mu.Lock(); defer s.mu.Unlock()
		end:=time.Since(s.start).Seconds()
		start:=s.lastIntervalEnd
		if s.firstEventAt!=nil { start=s.firstEventAt.Seconds() }
		seconds:=end-start; if seconds<0{seconds=0}
		streams:=[]jsonStream{}
		var sumBytesTrue, sumBytesFalse uint64; var hasTrue bool
		for _,ev:=range s.events {
			bps:=0.0; if seconds>0{bps=float64(ev.bytes)*8.0/seconds}
			streams=append(streams, jsonStream{ID:ev.id, Start:start, End:end, Seconds:seconds, Bytes:ev.bytes, BitsPerSecond:bps, Sender:ev.sender})
			if ev.sender { hasTrue=true; sumBytesTrue+=ev.bytes } else { sumBytesFalse+=ev.bytes }
		}
		sumSender:=hasTrue; sumBytes:=sumBytesTrue; if !hasTrue { sumSender=false; sumBytes=sumBytesFalse }
		sumbps:=0.0; if seconds>0{sumbps=float64(sumBytes)*8.0/seconds}
		sum:=jsonStream{Start:start, End:end, Seconds:seconds, Bytes:sumBytes, BitsPerSecond:sumbps, Sender:sumSender}
		if streams==nil{streams=[]jsonStream{}}
		s.intervals=append(s.intervals, jsonInterval{Streams:streams, Sum:sum})
		s.events=nil; s.firstEventAt=nil; s.lastIntervalEnd=end
	}
}
func (s *statsCollector) jsonBytes() ([]byte,error) {
	s.mu.Lock(); defer s.mu.Unlock()
	intervals:=s.intervals; if intervals==nil{intervals=[]jsonInterval{}}
	root:=map[string]interface{}{}
	_ = root
	// build manually to guarantee field order start, intervals
	type ts struct { Timesecs int64 `json:"timesecs"` }
	type startS struct { Timestamp ts `json:"timestamp"` }
	type doc struct { Start startS `json:"start"`; Intervals []jsonInterval `json:"intervals"` }
	d:=doc{Start:startS{Timestamp:ts{Timesecs:s.start.Unix()}}, Intervals:intervals}
	return json.Marshal(d)
}
func printStdout(s string) {
	logMu.Lock(); defer logMu.Unlock(); fmt.Fprint(os.Stdout, s)
}

// ---------- client helpers ----------
var errShutdown = fmt.Errorf("shutdown")
type clientRuntime struct {
	conn *Conn
	stats *statsCollector
	opts *ClientOpts
	errCh chan error
	doneFlag int32
}
func (rt *clientRuntime) reportErr(err error) {
	if atomic.LoadInt32(&rt.doneFlag)!=0 { return }
	select { case rt.errCh<-err: default: }
}
func zeroChunk() []byte { return make([]byte, 32768) }
var sharedZero = make([]byte, 32768)
func writeZeros(stream *QStream, total uint64) error {
	var written uint64
	for written<total {
		n:=uint64(len(sharedZero)); if total-written<n{n=total-written}
		if _,err:=stream.Write(sharedZero[:n]); err!=nil{return err}
		written+=n
	}
	return nil
}
func readDiscard(stream *QStream, onFirst func()) (uint64,error) {
	buf:=make([]byte,65536); var total uint64; first:=true
	for {
		n,err:=stream.Read(buf)
		if n>0 { if first && onFirst!=nil{onFirst()}; first=false; total+=uint64(n) }
		if err==io.EOF { return total,nil }
		if err!=nil { return total,err }
	}
}
func readExactStream(stream *QStream, buf []byte) error {
	var got int
	for got<len(buf) {
		n,err:=stream.Read(buf[got:]); if n>0{got+=n}; if err!=nil{return err}
	}
	return nil
}

func (rt *clientRuntime) biWorker() {
	for {
		if atomic.LoadInt32(&rt.doneFlag)!=0 { return }
		rec:=rt.stats.newRecord(); start:=time.Now()
		stream, err:=rt.conn.OpenStream(true); if err!=nil{ rt.reportErr(err); return }
		idx:=stream.Index(); logDebug("perf::client", fmt.Sprintf("sending request on client bidirectional stream %d", idx))
		header:=make([]byte,8); binary.BigEndian.PutUint64(header, rt.opts.DownloadSize)
		if _,err:=stream.Write(header); err!=nil{ stream.Close(); rt.reportErr(err); return }
		if rt.opts.UploadSize>0 {
			if err:=writeZeros(stream, rt.opts.UploadSize); err!=nil{ rt.reportErr(err); return }
			if err:=stream.Finish(); err!=nil{ rt.reportErr(err); return }
			logDebug("perf::client", fmt.Sprintf("upload finished on client bidirectional stream %d", idx))
			rt.stats.recordUpload(rec, stream.ID(), time.Since(start), rt.opts.UploadSize)
		} else {
			_ = stream.Finish()
		}
		if rt.opts.DownloadSize>0 {
			dlStart:=time.Now(); var firstAt *time.Time
			_, err:=readDiscard(stream, func(){ if firstAt==nil{ t:=time.Now(); firstAt=&t } })
			if err!=nil{ rt.reportErr(err); return }
			dlDur:=time.Since(dlStart); var fbl time.Duration; if firstAt!=nil{fbl=firstAt.Sub(dlStart)}
			logDebug("perf::client", fmt.Sprintf("response finished on client bidirectional stream %d", idx))
			rt.stats.recordDownload(rec, stream.ID(), dlDur, fbl, rt.opts.DownloadSize)
		}
		stream.Close()
	}
}
func (rt *clientRuntime) uniSendWorker() {
	for {
		if atomic.LoadInt32(&rt.doneFlag)!=0 { return }
		rec:=rt.stats.getUniRecord(0) // placeholder overwritten below; we need key by stream index, so create after opening
		_ = rec
		stream, err:=rt.conn.OpenStream(false); if err!=nil{ rt.reportErr(err); return }
		idx:=stream.Index(); rec = rt.stats.getUniRecord(idx); start:=rec.start
		logDebug("perf::client", fmt.Sprintf("sending request on client unidirectional stream %d", idx))
		header:=make([]byte,8); binary.BigEndian.PutUint64(header, rt.opts.DownloadSize)
		if _,err:=stream.Write(header); err!=nil{ rt.reportErr(err); return }
		if rt.opts.UploadSize>0 {
			if err:=writeZeros(stream, rt.opts.UploadSize); err!=nil{ rt.reportErr(err); return }
			if err:=stream.Finish(); err!=nil{ rt.reportErr(err); return }
			logDebug("perf::client", fmt.Sprintf("upload finished on client unidirectional stream %d", idx))
			rt.stats.recordUpload(rec, stream.ID(), time.Since(start), rt.opts.UploadSize)
		} else {
			_ = stream.Finish()
		}
		// uni sender does not wait for response
	}
}
func (rt *clientRuntime) uniRecvWorker() {
	for {
		if atomic.LoadInt32(&rt.doneFlag)!=0 { return }
		stream, err:=rt.conn.AcceptStream(false); if err!=nil{ if atomic.LoadInt32(&rt.doneFlag)==0 { rt.reportErr(err) }; return }
		go func(stream *QStream){
			idx:=stream.Index(); rec:=rt.stats.getUniRecord(idx); dlStart:=time.Now(); var firstAt *time.Time
			_, err:=readDiscard(stream, func(){ if firstAt==nil{t:=time.Now(); firstAt=&t} })
			if err!=nil{ if atomic.LoadInt32(&rt.doneFlag)==0 { rt.reportErr(err) }; return }
			dlDur:=time.Since(dlStart); var fbl time.Duration; if firstAt!=nil{fbl=firstAt.Sub(dlStart)}
			logDebug("perf::client", fmt.Sprintf("response finished on server unidirectional stream %d", idx))
			rt.stats.recordDownload(rec, stream.ID(), dlDur, fbl, rt.opts.DownloadSize)
			stream.Close()
		}(stream)
	}
}

func formatIPPort(ip net.IP, port uint16) string {
	if ip.To4()!=nil { return fmt.Sprintf("%s:%d", ip.String(), port) }
	return fmt.Sprintf("[%s]:%d", ip.String(), port)
}
func rustLookupErrorMsg(host string) string {
	// heuristic
	if host=="" || strings.ContainsAny(host, " []\t") { return "failed to lookup address information: Name or service not known" }
	return "failed to lookup address information: Temporary failure in name resolution"
}

// DNS resolution mimicking Rust std to_socket_addrs / tokio lookup_host for a string host (no --ip)
func resolveHostString(host string) (*net.UDPAddr, string, error) {
	// parsing port check for strings containing ':': second token after first colon must parse as u16, unless this is a valid bracketed IPv6 handled also by this rule (matches original)
	// But if no colon: resolving error
	if !strings.Contains(host, ":") {
		return nil, "", fmt.Errorf("resolving host: invalid socket address")
	}
	parts:=strings.Split(host, ":")
	// second token
	portTok:=parts[1]
	if _, reason:=parseU16Rust(portTok); reason!="" {
		return nil,"",fmt.Errorf("parsing port: %s", reason)
	}
	// valid socket literal?
	if addr,err:=net.ResolveUDPAddr("udp", host); err==nil && isIPLiteralHost(host) {
		return addr, hostNamePart(host), nil
	}
	// Multiple colons non-bracket leads to Rust invalid port value
	if !strings.HasPrefix(host, "[") && strings.Count(host, ":")>1 {
		return nil,"",fmt.Errorf("resolving host: invalid port value")
	}
	// bracketed non-IPv6 cases: Rust getaddrinfo fails Name or service
	if strings.HasPrefix(host, "[") {
		// Extract port after ]
		end:=strings.Index(host, "]")
		if end<0 { return nil,"",fmt.Errorf("resolving host: %s", rustLookupErrorMsg(host)) }
		inside:=host[1:end]
		if ip:=net.ParseIP(inside); ip!=nil && strings.Contains(inside, ":") {
			// would have failed port parse above for typical [::1]; unreachable
			return nil,"",fmt.Errorf("parsing port: cannot parse integer from empty string")
		}
		// Try lookup of inside without brackets specially: glibc with brackets fails
		return nil,"",fmt.Errorf("resolving host: failed to lookup address information: Name or service not known")
	}
	// split host and port at last colon
	idx:=strings.LastIndex(host, ":")
	hostPart:=host[:idx]; portPart:=host[idx+1:]
	port, reason:=parseU16Rust(portPart); if reason!="" { return nil,"",fmt.Errorf("parsing port: %s", reason) }
	// IP literal hostPart
	if ip:=net.ParseIP(hostPart); ip!=nil {
		return &net.UDPAddr{IP:ip, Port:int(port)}, hostPart, nil
	}
	// lookup
	ips, err:=net.LookupIP(hostPart)
	if err!=nil || len(ips)==0 {
		return nil,"",fmt.Errorf("resolving host: %s", rustLookupErrorMsg(hostPart))
	}
	// prefer IPv6
	chosen:=ips[0]
	for _,ip:=range ips { if ip.To4()==nil { chosen=ip; break } }
	return &net.UDPAddr{IP:chosen, Port:int(port)}, hostPart, nil
}
func parseU16Rust(s string) (uint16,string) {
	// parse as Rust u16: empty, invalid, overflow >65535
	if s=="" { return 0,"cannot parse integer from empty string" }
	v, reason:=parseU64Rust(s)
	if reason!="" {
		// Rust u16 overflow message is same 'number too large...' but our parseU64 would accept up to u64
		return 0,reason
	}
	if v>65535 { return 0,"number too large to fit in target type" }
	return uint16(v),""
}
func isIPLiteralHost(host string) bool {
	if strings.HasPrefix(host,"[") {
		end:=strings.Index(host,"]"); if end<0{return false}; return net.ParseIP(host[1:end])!=nil
	}
	idx:=strings.LastIndex(host,":"); if idx<0{return false}; return net.ParseIP(host[:idx])!=nil
}
func hostNamePart(host string) string {
	// first token split by ':'
	if i:=strings.Index(host, ":"); i>=0 { return host[:i] }
	return host
}

func validateServerName(name string) error {
	if ip:=net.ParseIP(name); ip!=nil { return nil }
	// must be valid IP if it looks numeric-only labels?
	if name=="" { return fmt.Errorf("invalid server name: %s", name) }
	// DNS validation
	if len(name)>253 { return fmt.Errorf("invalid server name: %s", name) }
	labels:=strings.Split(name, ".")
	for _,l:=range labels {
		if l=="" || len(l)>63 { return fmt.Errorf("invalid server name: %s", name) }
		if l[0]=='-' || l[len(l)-1]=='-' { return fmt.Errorf("invalid server name: %s", name) }
		for _,c:=range l {
			if !((c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')||c=='-'||c=='_') { return fmt.Errorf("invalid server name: %s", name) }
		}
	}
	last:=labels[len(labels)-1]
	allNum:=true; for _,c:=range last{ if c<'0'||c>'9'{allNum=false} }
	if allNum { return fmt.Errorf("invalid server name: %s", name) }
	return nil
}

func runClient(opts *ClientOpts) error {
	// Resolve
	var remote *net.UDPAddr
	var serverName string
	if opts.IPSet {
		// port from host split nth(1) or 443
		parts:=strings.Split(opts.Host, ":")
		serverName=parts[0]
		portStr:="443"
		if len(parts)>1 { portStr=parts[1] }
		port, reason:=parseU16Rust(portStr); if reason!="" { return fmt.Errorf("parsing port: %s", reason) }
		remote=&net.UDPAddr{IP:*opts.IP, Port:int(port)}
	} else {
		addr, _, err:=resolveHostString(opts.Host); if err!=nil{ return err }
		remote=addr; serverName=hostNamePart(opts.Host)
	}
	// local addr determination
	var localAddr *net.UDPAddr
	if opts.LocalSet {
		la, err:=resolveUDPAddrFromString(opts.LocalAddr); if err!=nil{ return fmt.Errorf("binding endpoint: %s", rustOsError(err)) }
		localAddr=la
	} else {
		if remote.IP!=nil && remote.IP.To4()!=nil { localAddr=&net.UDPAddr{IP:net.IPv4zero, Port:0} } else { localAddr=&net.UDPAddr{IP:net.IPv6zero, Port:0} }
	}
	logInfo("perf::client", fmt.Sprintf("connecting to %s at %s", serverName, remote.String()))
	logInfo("perf::client", fmt.Sprintf("local addr %s", localAddr.String()))
	udp, err:=createSocket(localAddr, opts.SendBufferSize, opts.RecvBufferSize)
	if err!=nil { return fmt.Errorf("binding endpoint: %s", rustOsError(err)) }
	// transport validation
	if err:=checkMaxUDP(opts.MaxUdpPayloadSize); err!=nil{ udp.Close(); return err }
	// qlog
	var qlogW *qlogWriter
	if opts.QlogSet {
		qw, err:=newQlogWriter(opts.Qlog, "perf-client"); if err!=nil{ udp.Close(); return fmt.Errorf("%s", rustOsError(err)) }
		qlogW=qw
	}
	keylog:=newKeyLogFile(opts.Keylog)
	// validate server name
	if err:=validateServerName(serverName); err!=nil{ udp.Close(); return err }
	// invalid remote address family check: if local socket is IPv4 and remote IPv6
	if la,ok:=udp.LocalAddr().(*net.UDPAddr); ok && la.IP!=nil && la.IP.To4()!=nil && remote.IP!=nil && remote.IP.To4()==nil {
		udp.Close(); return fmt.Errorf("invalid remote address: %s", remote.String())
	}
	cfg:=QUICConfig{Common:commonToQUIC(opts.CommonOpts), IsServer:false, Qlog:qlogW, KeyLog:keylog, ALPN:nil}
	conn, err:=DialQUIC(udp, remote, serverName, cfg)
	if err!=nil {
		// DialQUIC closes udp on error
		return fmt.Errorf("connecting: %s", err.Error())
	}
	logInfo("perf::client", "established")
	stats:=newStatsCollector(opts.JsonSet, opts.UploadSize, opts.DownloadSize)
	rt:=&clientRuntime{conn:conn, stats:stats, opts:opts, errCh:make(chan error,16)}
	// workers
	for i:=uint64(0); i<opts.BiRequests; i++ { go rt.biWorker() }
	for i:=uint64(0); i<opts.UniRequests; i++ { go rt.uniSendWorker() }
	if opts.DownloadSize>0 && opts.UniRequests>0 { go rt.uniRecvWorker() }
	// main timing loop
	duration:=time.Duration(opts.Duration)*time.Second
	interval:=time.Duration(opts.Interval)*time.Second
	start:=time.Now()
	durationTimer:=time.NewTimer(duration)
	var tickTimer *time.Timer
	resetTick:=func(){
		if tickTimer!=nil { tickTimer.Stop() }
		// first tick after interval; if interval==0, immediate repeating via 0 timer
		tickTimer=time.NewTimer(interval)
	}
	resetTick()
	var workerErr error
runLoop:
	for {
		select {
		case <-durationTimer.C:
			break runLoop
		case err:=<-rt.errCh:
			workerErr=err; break runLoop
		case <-tickTimer.C:
			stats.printStats()
			// schedule next tick anchored; for interval 0 set tiny
			if interval==0 { tickTimer=time.NewTimer(0) } else { tickTimer=time.NewTimer(interval) }
			_ = start
		}
	}
	if workerErr!=nil {
		logError("perf::client", fmt.Sprintf("request failed: %s", workerErr.Error()))
	}
	atomic.StoreInt32(&rt.doneFlag,1)
	// conn stats printed before shutting down (as observed)
	if opts.ConnStats { printStdout(conn.StatsString()+"\n") }
	// grace approx 200ms after duration end (but if worker error, no grace? original dur0 showed shutting down 200ms after established)
	if workerErr==nil {
		time.Sleep(200*time.Millisecond)
	}
	logInfo("perf::client", "shutting down")
	conn.Close(0, "done")
	// JSON write
	if opts.JsonSet {
		data, err:=stats.jsonBytes(); if err==nil {
			if opts.Json=="-" { printStdout(string(data)) } else {
				if err:=os.WriteFile(opts.Json, data, 0644); err!=nil{ return fmt.Errorf("%s", rustOsError(err)) }
			}
		}
	}
	return nil
}
// ---------- server ----------
func runServer(opts *ServerOpts) (err error) {
	defer func(){ if r:=recover(); r!=nil { if le,ok:=r.(loadError); ok { err=fmt.Errorf("%s", le.msg); return }; panic(r) } }()
	var certChain [][]byte; var signer interface{}
	var qlogW *qlogWriter
	// key/cert loading first (or self-signed)
	certs, sig := loadServerCert(opts)
	certChain=certs; signer=sig
	// qlog before endpoint (per observed ordering)
	if opts.QlogSet {
		qw, err2:=newQlogWriter(opts.Qlog, "perf-server"); if err2!=nil{ return fmt.Errorf("%s", rustOsError(err2)) }
		qlogW=qw
	}
	keylog:=newKeyLogFile(opts.Keylog)
	listenAddr, err:=resolveUDPAddrFromString(opts.Listen); if err!=nil{ return fmt.Errorf("binding endpoint: %s", rustOsError(err)) }
	udp, err:=createSocket(listenAddr, opts.SendBufferSize, opts.RecvBufferSize)
	if err!=nil{ return fmt.Errorf("binding endpoint: %s", rustOsError(err)) }
	// transport validation after endpoint socket creation
	if err:=checkMaxUDP(opts.MaxUdpPayloadSize); err!=nil{ udp.Close(); return err }
	cfg:=QUICConfig{Common:commonToQUIC(opts.CommonOpts), IsServer:true, CertChain:certChain, Qlog:qlogW, KeyLog:keylog}
	if cs,ok:=signer.(interface{}); ok { _ = cs }
	// signer type is crypto.Signer; loadServerCert returned that
	cfg.Signer = sig
	endpoint:=NewServerEndpoint(udp, cfg)
	logInfo("perf::server", fmt.Sprintf("listening on %s", listenAddr.String()))
	for {
		conn, err:=endpoint.AcceptConn(); if err!=nil{ return err }
		go handleServerConn(conn, opts)
	}
}
func handleServerConn(conn *Conn, opts *ServerOpts) {
	// wait established
	errCh:=make(chan error,1)
	go func(){
		// poll
		for {
			if conn.IsEstablished(){ errCh<-nil; return }
			select { case <-conn.Done(): 
				conn.mu.Lock(); e:=conn.handshakeErr; if e==nil{e=conn.closeErr}; conn.mu.Unlock(); errCh<-e; return
			case <-time.After(10*time.Millisecond): }
		}
	}()
	if err:=<-errCh; err!=nil {
		msg:=err.Error()
		logError("perf::server", fmt.Sprintf("connection lost: handshake failed: %s", msg))
		return
	}
	logDebug("perf::server", fmt.Sprintf("%s connected", conn.remote.String()))
	// accept loops
	go serverAcceptLoop(conn, opts, true)
	go serverAcceptLoop(conn, opts, false)
	// wait done
	<-conn.Done()
	if opts.ConnStats {
		// small delay to allow stats to settle? print immediately
		printStdout(conn.StatsString()+"\n")
	}
}
func serverAcceptLoop(conn *Conn, opts *ServerOpts, bidi bool) {
	for {
		stream, err:=conn.AcceptStream(bidi); if err!=nil{ return }
		if bidi { go handleServerBidi(conn, stream) } else { go handleServerUni(conn, stream) }
	}
}
func handleServerBidi(conn *Conn, stream *QStream) {
	// read header
	hdr:=make([]byte,8)
	if err:=readExactStream(stream, hdr); err!=nil{
		// if EOF before any byte and connection normal? Original may log only if error is not EOF due client closing empty stream; approximate ignore EOF?
		logError("perf::server", fmt.Sprintf("request failed: reading request: %s", appErrString(err)))
		return
	}
	size:=binary.BigEndian.Uint64(hdr)
	logDebug("perf::server", fmt.Sprintf("got req for %d bytes on client bidirectional stream %d", size, stream.Index()))
	if _,err:=readDiscard(stream,nil); err!=nil{ logError("perf::server", fmt.Sprintf("request failed: reading request: %s", appErrString(err))); return }
	logDebug("perf::server", fmt.Sprintf("finished reading client bidirectional stream %d", stream.Index()))
	if err:=writeZeros(stream,size); err!=nil{ logError("perf::server", fmt.Sprintf("request failed: sending response: %s", appErrString(err))); return }
	if err:=stream.Finish(); err!=nil{ logError("perf::server", fmt.Sprintf("request failed: sending response: %s", appErrString(err))); return }
	logDebug("perf::server", fmt.Sprintf("finished responding on client bidirectional stream %d", stream.Index()))
	stream.Close()
}
func handleServerUni(conn *Conn, stream *QStream) {
	hdr:=make([]byte,8)
	if err:=readExactStream(stream, hdr); err!=nil{ logError("perf::server", fmt.Sprintf("request failed: reading request: %s", appErrString(err))); return }
	size:=binary.BigEndian.Uint64(hdr)
	logDebug("perf::server", fmt.Sprintf("got req for %d bytes on client unidirectional stream %d", size, stream.Index()))
	if _,err:=readDiscard(stream,nil); err!=nil{ logError("perf::server", fmt.Sprintf("request failed: reading request: %s", appErrString(err))); return }
	logDebug("perf::server", fmt.Sprintf("finished reading client unidirectional stream %d", stream.Index()))
	// open uni back
	resp, err:=conn.OpenStream(false); if err!=nil{ logError("perf::server", fmt.Sprintf("request failed: sending response: %s", appErrString(err))); return }
	if err:=writeZeros(resp,size); err!=nil{ logError("perf::server", fmt.Sprintf("request failed: sending response: %s", appErrString(err))); return }
	if err:=resp.Finish(); err!=nil{ logError("perf::server", fmt.Sprintf("request failed: sending response: %s", appErrString(err))); return }
	logDebug("perf::server", fmt.Sprintf("finished responding on server unidirectional stream %d", resp.Index()))
	resp.Close(); stream.Close()
}
func appErrString(err error) string {
	if err==io.EOF { return "connection lost: closed" }
	return err.Error()
}
