func createSocket(addr *net.UDPAddr, sendSize, recvSize uint64) (*net.UDPConn, error) {
	network := "udp"
	if addr.IP != nil {
		if addr.IP.To4() != nil { network = "udp4" } else { network = "udp6" }
	}
	conn, err := net.ListenUDP(network, addr)
	if err != nil {
		return nil, err
	}
	// set buffers after bind, warn if actual < desired, in order send/recv
	setBuf := func(send bool, desired uint64) {
		raw, err := conn.SyscallConn()
		if err != nil { return }
		var actual int
		var setErr error
		raw.Control(func(fd uintptr) {
			opt := syscall.SO_SNDBUF
			if !send { opt = syscall.SO_RCVBUF }
			d := desired
			if d > 2147483647 { d = 2147483647 }
			// syscall on linux
			_ = syscall.SetsockoptInt(int(fd), syscall.SOL_SOCKET, opt, int(d))
			actual, setErr = syscall.GetsockoptInt(int(fd), syscall.SOL_SOCKET, opt)
		})
		_ = setErr
		if uint64(actual) < desired {
			if send {
				logWarn("perf", fmt.Sprintf("Unable to set desired send buffer size. Desired: %d, Actual: %d", desired, actual))
			} else {
				logWarn("perf", fmt.Sprintf("Unable to set desired recv buffer size. Desired: %d, Actual: %d", desired, actual))
			}
		}
	}
	setBuf(true, sendSize)
	setBuf(false, recvSize)
	return conn, nil
}
