		}
	}
	last:=labels[len(labels)-1]
	allNum:=true; for _,c:=range last{ if c<'0'||c>'9'{allNum=false} }
	if allNum { return fmt.Errorf("invalid server name: %s", name) }
	return nil
}

func runClient(opts *ClientOpts) error {
	// Resolve
	var remote *net.UDPAddr
	var serverName string
	if opts.IPSet {
		// port from host split nth(1) or 443
		parts:=strings.Split(opts.Host, ":")
		serverName=parts[0]
		portStr:="443"
		if len(parts)>1 { portStr=parts[1] }
		port, reason:=parseU16Rust(portStr); if reason!="" { return fmt.Errorf("parsing port: %s", reason) }
		remote=&net.UDPAddr{IP:*opts.IP, Port:int(port)}
	} else {
		addr, _, err:=resolveHostString(opts.Host); if err!=nil{ return err }
		remote=addr; serverName=hostNamePart(opts.Host)
	}
	// local addr determination
	var localAddr *net.UDPAddr
	if opts.LocalSet {
		la, err:=resolveUDPAddrFromString(opts.LocalAddr); if err!=nil{ return fmt.Errorf("binding endpoint: %s", rustOsError(err)) }
		localAddr=la
	} else {
		if remote.IP!=nil && remote.IP.To4()!=nil { localAddr=&net.UDPAddr{IP:net.IPv4zero, Port:0} } else { localAddr=&net.UDPAddr{IP:net.IPv6zero, Port:0} }
	}
	logInfo("perf::client", fmt.Sprintf("connecting to %s at %s", serverName, remote.String()))
	logInfo("perf::client", fmt.Sprintf("local addr %s", localAddr.String()))
	udp, err:=createSocket(localAddr, opts.SendBufferSize, opts.RecvBufferSize)
	if err!=nil { return fmt.Errorf("binding endpoint: %s", rustOsError(err)) }
	// transport validation
	if err:=checkMaxUDP(opts.MaxUdpPayloadSize); err!=nil{ udp.Close(); return err }
	// qlog
	var qlogW *qlogWriter
	if opts.QlogSet {
		qw, err:=newQlogWriter(opts.Qlog, "perf-client"); if err!=nil{ udp.Close(); return fmt.Errorf("%s", rustOsError(err)) }
		qlogW=qw
	}
	keylog:=newKeyLogFile(opts.Keylog)
	// validate server name
	if err:=validateServerName(serverName); err!=nil{ udp.Close(); return err }
	// invalid remote address family check: if local socket is IPv4 and remote IPv6
	if la,ok:=udp.LocalAddr().(*net.UDPAddr); ok && la.IP!=nil && la.IP.To4()!=nil && remote.IP!=nil && remote.IP.To4()==nil {
		udp.Close(); return fmt.Errorf("invalid remote address: %s", remote.String())
	}
	cfg:=QUICConfig{Common:commonToQUIC(opts.CommonOpts), IsServer:false, Qlog:qlogW, KeyLog:keylog, ALPN:nil}
	conn, err:=DialQUIC(udp, remote, serverName, cfg)
	if err!=nil {
		// DialQUIC closes udp on error
		return fmt.Errorf("connecting: %s", err.Error())
	}
	logInfo("perf::client", "established")
	stats:=newStatsCollector(opts.JsonSet, opts.UploadSize, opts.DownloadSize)
	rt:=&clientRuntime{conn:conn, stats:stats, opts:opts, errCh:make(chan error,16)}
	// workers
	for i:=uint64(0); i<opts.BiRequests; i++ { go rt.biWorker() }
	for i:=uint64(0); i<opts.UniRequests; i++ { go rt.uniSendWorker() }
	if opts.DownloadSize>0 && opts.UniRequests>0 { go rt.uniRecvWorker() }
	// main timing loop
	duration:=time.Duration(opts.Duration)*time.Second
	interval:=time.Duration(opts.Interval)*time.Second
	start:=time.Now()
	durationTimer:=time.NewTimer(duration)
	var tickTimer *time.Timer
	resetTick:=func(){
		if tickTimer!=nil { tickTimer.Stop() }
		// first tick after interval; if interval==0, immediate repeating via 0 timer
		tickTimer=time.NewTimer(interval)
	}
	resetTick()
	var workerErr error
runLoop:
	for {
		select {
		case <-durationTimer.C:
			break runLoop
		case err:=<-rt.errCh:
			workerErr=err; break runLoop
		case <-tickTimer.C:
			stats.printStats()
			// schedule next tick anchored; for interval 0 set tiny
			if interval==0 { tickTimer=time.NewTimer(0) } else { tickTimer=time.NewTimer(interval) }
			_ = start
		}
	}
	if workerErr!=nil {
		logError("perf::client", fmt.Sprintf("request failed: %s", workerErr.Error()))
	}
	atomic.StoreInt32(&rt.doneFlag,1)
	// conn stats printed before shutting down (as observed)
	if opts.ConnStats { printStdout(conn.StatsString()+"\n") }
	// grace approx 200ms after duration end (but if worker error, no grace? original dur0 showed shutting down 200ms after established)
	if workerErr==nil {
		time.Sleep(200*time.Millisecond)
	}
	logInfo("perf::client", "shutting down")
	conn.Close(0, "done")
	// JSON write
	if opts.JsonSet {
		data, err:=stats.jsonBytes(); if err==nil {
			if opts.Json=="-" { printStdout(string(data)) } else {
				if err:=os.WriteFile(opts.Json, data, 0644); err!=nil{ return fmt.Errorf("%s", rustOsError(err)) }
			}
		}
	}
	return nil
}
// ---------- server ----------
func runServer(opts *ServerOpts) (err error) {
	defer func(){ if r:=recover(); r!=nil { if le,ok:=r.(loadError); ok { err=fmt.Errorf("%s", le.msg); return }; panic(r) } }()
	var certChain [][]byte; var signer interface{}
	var qlogW *qlogWriter
	// key/cert loading first (or self-signed)
	certs, sig := loadServerCert(opts)
	certChain=certs; signer=sig
	// qlog before endpoint (per observed ordering)
	if opts.QlogSet {
		qw, err2:=newQlogWriter(opts.Qlog, "perf-server"); if err2!=nil{ return fmt.Errorf("%s", rustOsError(err2)) }
		qlogW=qw
	}
	keylog:=newKeyLogFile(opts.Keylog)
	listenAddr, err:=resolveUDPAddrFromString(opts.Listen); if err!=nil{ return fmt.Errorf("binding endpoint: %s", rustOsError(err)) }
	udp, err:=createSocket(listenAddr, opts.SendBufferSize, opts.RecvBufferSize)
	if err!=nil{ return fmt.Errorf("binding endpoint: %s", rustOsError(err)) }
	// transport validation after endpoint socket creation
	if err:=checkMaxUDP(opts.MaxUdpPayloadSize); err!=nil{ udp.Close(); return err }
	cfg:=QUICConfig{Common:commonToQUIC(opts.CommonOpts), IsServer:true, CertChain:certChain, Qlog:qlogW, KeyLog:keylog}
	if cs,ok:=signer.(interface{}); ok { _ = cs }
	// signer type is crypto.Signer; loadServerCert returned that
	cfg.Signer = sig
	endpoint:=NewServerEndpoint(udp, cfg)
	logInfo("perf::server", fmt.Sprintf("listening on %s", listenAddr.String()))
	for {
		conn, err:=endpoint.AcceptConn(); if err!=nil{ return err }
		go handleServerConn(conn, opts)
	}
}
func handleServerConn(conn *Conn, opts *ServerOpts) {
	// wait established
	errCh:=make(chan error,1)
	go func(){
		// poll
		for {
			if conn.IsEstablished(){ errCh<-nil; return }
			select { case <-conn.Done(): 
				conn.mu.Lock(); e:=conn.handshakeErr; if e==nil{e=conn.closeErr}; conn.mu.Unlock(); errCh<-e; return
			case <-time.After(10*time.Millisecond): }
		}
	}()
	if err:=<-errCh; err!=nil {
		msg:=err.Error()
		logError("perf::server", fmt.Sprintf("connection lost: handshake failed: %s", msg))
		return
	}
	logDebug("perf::server", fmt.Sprintf("%s connected", conn.remote.String()))
	// accept loops
	go serverAcceptLoop(conn, opts, true)
	go serverAcceptLoop(conn, opts, false)
	// wait done
	<-conn.Done()
	if opts.ConnStats {
		// small delay to allow stats to settle? print immediately
		printStdout(conn.StatsString()+"\n")
	}
}
func serverAcceptLoop(conn *Conn, opts *ServerOpts, bidi bool) {
	for {
		stream, err:=conn.AcceptStream(bidi); if err!=nil{ return }
		if bidi { go handleServerBidi(conn, stream) } else { go handleServerUni(conn, stream) }
	}
}
func handleServerBidi(conn *Conn, stream *QStream) {
	// read header
	hdr:=make([]byte,8)
	if err:=readExactStream(stream, hdr); err!=nil{
		// if EOF before any byte and connection normal? Original may log only if error is not EOF due client closing empty stream; approximate ignore EOF?
		logError("perf::server", fmt.Sprintf("request failed: reading request: %s", appErrString(err)))
		return
	}
	size:=binary.BigEndian.Uint64(hdr)
	logDebug("perf::server", fmt.Sprintf("got req for %d bytes on client bidirectional stream %d", size, stream.Index()))
	if _,err:=readDiscard(stream,nil); err!=nil{ logError("perf::server", fmt.Sprintf("request failed: reading request: %s", appErrString(err))); return }
	logDebug("perf::server", fmt.Sprintf("finished reading client bidirectional stream %d", stream.Index()))
	if err:=writeZeros(stream,size); err!=nil{ logError("perf::server", fmt.Sprintf("request failed: sending response: %s", appErrString(err))); return }
	if err:=stream.Finish(); err!=nil{ logError("perf::server", fmt.Sprintf("request failed: sending response: %s", appErrString(err))); return }
	logDebug("perf::server", fmt.Sprintf("finished responding on client bidirectional stream %d", stream.Index()))
	stream.Close()
}
func handleServerUni(conn *Conn, stream *QStream) {
	hdr:=make([]byte,8)
	if err:=readExactStream(stream, hdr); err!=nil{ logError("perf::server", fmt.Sprintf("request failed: reading request: %s", appErrString(err))); return }
	size:=binary.BigEndian.Uint64(hdr)
	logDebug("perf::server", fmt.Sprintf("got req for %d bytes on client unidirectional stream %d", size, stream.Index()))
	if _,err:=readDiscard(stream,nil); err!=nil{ logError("perf::server", fmt.Sprintf("request failed: reading request: %s", appErrString(err))); return }
	logDebug("perf::server", fmt.Sprintf("finished reading client unidirectional stream %d", stream.Index()))
	// open uni back
	resp, err:=conn.OpenStream(false); if err!=nil{ logError("perf::server", fmt.Sprintf("request failed: sending response: %s", appErrString(err))); return }
	if err:=writeZeros(resp,size); err!=nil{ logError("perf::server", fmt.Sprintf("request failed: sending response: %s", appErrString(err))); return }
	if err:=resp.Finish(); err!=nil{ logError("perf::server", fmt.Sprintf("request failed: sending response: %s", appErrString(err))); return }
	logDebug("perf::server", fmt.Sprintf("finished responding on server unidirectional stream %d", resp.Index()))
	resp.Close(); stream.Close()
}
func appErrString(err error) string {
	if err==io.EOF { return "connection lost: closed" }
	return err.Error()
}
