{"command":"python3 - << 'PY'
import pathlib
p=pathlib.Path("quic.go"); s=p.read_text(); old_start=s.index("func reconstructPN"); old_end=s.index("// ---------- packet send ----------", old_start)
new='''func reconstructPN(largest uint64, hasLargest bool, truncated uint64, pnLen int) uint64 {
	if !hasLargest {
		return truncated
	}
	expected := int64(largest + 1)
	win := int64(1) << uint(pnLen*8)
	half := win / 2
	mask := ^(win - 1)
	candidate := (expected & mask) | int64(truncated)
	if candidate <= expected-half && candidate < (int64(1)<<62)-win {
		candidate += win
	} else if candidate > expected+half && candidate >= win {
		candidate -= win
	}
	if candidate < 0 { candidate = int64(truncated) }
	return uint64(candidate)
}

'''
s=s[:old_start]+new+s[old_end:]; p.write_text(s)
PY
