{"command":"python3 - << 'PY'
import pathlib
p=pathlib.Path("perf.go"); s=p.read_text()
old_start=s.index("\t// main timing loop")
old_end=s.index("\tif workerErr!=nil {", old_start)
new='''\t// main timing loop
\tduration:=time.Duration(opts.Duration)*time.Second
\tinterval:=time.Duration(opts.Interval)*time.Second
\tstart:=time.Now()
\tend:=start.Add(duration)
\tnextTick:=start.Add(interval)
\tif interval==0 { nextTick=start }
\tvar workerErr error
runLoop:
\tfor {
\t\t// prioritize worker errors that already arrived
\t\tselect { case err:=<-rt.errCh: workerErr=err; break runLoop; default: }
\t\tnow:=time.Now()
\t\tif !nextTick.After(end) && !now.Before(nextTick) {
\t\t\tstats.printStats()
\t\t\tif interval==0 { nextTick=time.Now() } else {
\t\t\t\tnextTick=nextTick.Add(interval)
\t\t\t\tif nextTick.Before(now) && interval>0 { /* keep schedule, may catch up one tick at a time */ }
\t\t\t}
\t\t\tcontinue
\t\t}
\t\tif !now.Before(end) { break runLoop }
\t\twaitUntil:=end; if nextTick.Before(waitUntil) { waitUntil=nextTick }
\t\td:=time.Until(waitUntil); if d<0{d=0}
\t\ttimer:=time.NewTimer(d)
\t\tselect {
\t\tcase <-timer.C:
\t\tcase err:=<-rt.errCh: timer.Stop(); workerErr=err; break runLoop
\t\t}
\t}
'''
s=s[:old_start]+new+s[old_end:]
p.write_text(s)
PY
gofmt -w perf.go; go build -o /tmp/a/executable . && timeout 10 /tmp/a/executable client --help >/dev/null && echo ok"}

