package main

import (
	"crypto"
	"crypto/aes"
	"crypto/cipher"
	"encoding/binary"
	"encoding/hex"
	"fmt"
	"hash"
	"os"
	"strings"
	"testing"
)

func expandLabelFull(h crypto.Hash, secret []byte, fullLabel string, ctx []byte, length int) []byte {
	var info []byte
	info = append(info, byte(length>>8), byte(length))
	info = append(info, byte(len(fullLabel)))
	info = append(info, fullLabel...)
	info = append(info, byte(len(ctx)))
	info = append(info, ctx...)
	return hkdfExpand(h, secret, info, length)
}

func TestBrute(t *testing.T) {
	data, err := os.ReadFile("/tmp/brute_input.txt")
	if err != nil { t.Skip("no input") }
	lines := strings.Split(strings.TrimSpace(string(data)), "\n")
	secrets := map[string][]byte{}
	names := []string{"clientApp", "serverApp", "suite", "hs", "master", "clientHs", "serverHs"}
	for i, n := range names {
		if i < len(lines) {
			b, _ := hex.DecodeString(strings.TrimSpace(lines[i]))
			secrets[n] = b
		}
	}
	var raws [][]byte
	for _, l := range lines {
		if strings.HasPrefix(l, "RAW ") {
			b, _ := hex.DecodeString(strings.TrimSpace(l[4:]))
			raws = append(raws, b)
		}
	}
	fmt.Println("secrets", secrets["clientApp"], "raws", len(raws))
	if len(raws) == 0 { t.Fatal("no raws") }
	raw := raws[0]
	pnOff := 9
	sample := raw[pnOff+4 : pnOff+4+16]
	hashes := []crypto.Hash{crypto.SHA256, crypto.SHA384}
	type updCfg struct{ label, prefix string; ctx []byte; iters int }
	var updCfgs []updCfg
	for _, lab := range []string{"quic ku", "ku", "quic key update", "traffic upd", "quic_key_update"} {
		for _, pre := range []string{"tls13 ", "", "quic "} {
			for _, ctx := range [][]byte{{}, hashBytes(crypto.SHA256, nil), hashBytes(crypto.SHA384, nil)} {
				for it := 1; it <= 3; it++ {
					updCfgs = append(updCfgs, updCfg{lab, pre, ctx, it})
				}
			}
		}
	}
	type keyCfg struct {
		name string
		derive func(secret []byte, h crypto.Hash) *keyMaterial
	}
	var keyCfgs []keyCfg
	for _, pre := range []string{"tls13 ", ""} {
		for _, kl := range []int{16, 32} {
			pre, kl := pre, kl
			keyCfgs = append(keyCfgs, keyCfg{fmt.Sprintf("std pre=%q kl=%d", pre, kl), func(secret []byte, h crypto.Hash) *keyMaterial {
				return &keyMaterial{
					key: expandLabelFull(h, secret, pre+"quic key", nil, kl),
					iv:  expandLabelFull(h, secret, pre+"quic iv", nil, 12),
					hp:  expandLabelFull(h, secret, pre+"quic hp", nil, kl),
				}
			}})
		}
	}
	// direct key
	keyCfgs = append(keyCfgs, keyCfg{"direct16", func(secret []byte, h crypto.Hash) *keyMaterial {
		if len(secret) < 16 { return nil }
		return &keyMaterial{key: secret[:16], iv: expandLabelFull(h, secret, "tls13 quic iv", nil, 12), hp: expandLabelFull(h, secret, "tls13 quic hp", nil, 16)}
	}})

	tryDecrypt := func(km *keyMaterial, h crypto.Hash) (uint64, []byte, bool) {
		if km == nil { return 0, nil, false }
		block, err := aes.NewCipher(km.hp)
		if err != nil { return 0, nil, false }
		maskFull := make([]byte, 16)
		block.Encrypt(maskFull, sample)
		first := raw[0] ^ (maskFull[0] & 0x1f)
		pl := int(first&0x03) + 1
		if pnOff+pl >= len(raw) { return 0, nil, false }
		hdr := make([]byte, pnOff+pl)
		copy(hdr, raw[:pnOff+pl])
		hdr[0] = first
		var trunc uint64
		for i := 0; i < pl; i++ {
			hdr[pnOff+i] = raw[pnOff+i] ^ maskFull[1+i]
			trunc = (trunc << 8) | uint64(hdr[pnOff+i])
		}
		step := uint64(1) << uint(8*pl)
		// PN candidates: near 0..3000 matching trunc, plus reconstruct
		var pns []uint64
		for pn := trunc; pn < 3000; pn += step { pns = append(pns, pn) }
		for _, pn := range pns {
			var suite *cipherSuite
			if len(km.key) == 32 { suite = suiteAES256 } else { suite = suiteAES128 }
			_ = suite
			block2, err := aes.NewCipher(km.key)
			if err != nil { continue }
			gcm, err := cipher.NewGCM(block2)
			if err != nil { continue }
			nonce := make([]byte, 12)
			copy(nonce, km.iv)
			for i := 0; i < 8; i++ { nonce[4+i] ^= byte(pn >> uint(56-8*i)) }
			pt, err := gcm.Open(nil, nonce, raw[pnOff+pl:], hdr)
			if err == nil { return pn, pt, true }
		}
		return 0, nil, false
	}
	_ = hashes
	for hname, base := range secrets {
		if hname == "suite" || len(base) == 0 { continue }
		for _, h := range []crypto.Hash{crypto.SHA256, crypto.SHA384} {
			// base itself
			for _, kc := range keyCfgs {
				if pn, pt, ok := tryDecrypt(kc.derive(base, h), h); ok {
					fmt.Printf("FOUND base=%s hash=%v keycfg=%s pn=%d pt=%x\n", hname, h, kc.name, pn, pt)
					return
				}
			}
			for _, uc := range updCfgs {
				s := base
				for i := 0; i < uc.iters; i++ {
					s = expandLabelFull(h, s, uc.prefix+uc.label, uc.ctx, h.Size())
				}
				for _, kc := range keyCfgs {
					if pn, pt, ok := tryDecrypt(kc.derive(s, h), h); ok {
						fmt.Printf("FOUND base=%s hash=%v upd=%+v keycfg=%s pn=%d pt=%x\n", hname, h, uc, kc.name, pn, pt)
						return
					}
				}
			}
		}
	}
	fmt.Println("NOT FOUND")
	var _ hash.Hash
	_ = binary.BigEndian
}
