import pathlib
p=pathlib.Path("quic.go"); s=p.read_text()

# 1. struct field
s = s.replace("\trecvPNs         map[uint64]bool\n", "\trecvRanges      []pnRange\n", 1)

# 2. newPnSpace init
s = s.replace("return &pnSpace{id: id, recvPNs: map[uint64]bool{}, cryptoSend: &sendBuffer{}, cryptoRecv: &recvBuffer{}, sent: map[uint64]*sentPacket{}}",
              "return &pnSpace{id: id, cryptoSend: &sendBuffer{}, cryptoRecv: &recvBuffer{}, sent: map[uint64]*sentPacket{}}", 1)

# add pnRange type + helpers after pnSpace struct closing (insert before "func newPnSpace")
anchor = "func newPnSpace(id int) *pnSpace {"
helpers = '''type pnRange struct{ lo, hi uint64 }

func (sp *pnSpace) pnReceived(pn uint64) bool {
	i := sort.Search(len(sp.recvRanges), func(i int) bool { return sp.recvRanges[i].hi >= pn })
	if i < len(sp.recvRanges) {
		r := sp.recvRanges[i]
		if pn >= r.lo && pn <= r.hi {
			return true
		}
	}
	return false
}
func (sp *pnSpace) pnMark(pn uint64) {
	if sp.pnReceived(pn) {
		return
	}
	// Insert and merge with neighbors (ranges sorted ascending by lo)
	r := pnRange{pn, pn}
	i := sort.Search(len(sp.recvRanges), func(i int) bool { return sp.recvRanges[i].lo > pn })
	// merge with previous
	if i > 0 && sp.recvRanges[i-1].hi+1 >= r.lo {
		i--
		if sp.recvRanges[i].lo < r.lo {
			r.lo = sp.recvRanges[i].lo
		}
		if sp.recvRanges[i].hi > r.hi {
			r.hi = sp.recvRanges[i].hi
		}
		sp.recvRanges = append(sp.recvRanges[:i], sp.recvRanges[i+1:]...)
	}
	// merge with next (now at index i)
	if i < len(sp.recvRanges) && r.hi+1 >= sp.recvRanges[i].lo {
		if sp.recvRanges[i].hi > r.hi {
			r.hi = sp.recvRanges[i].hi
		}
		sp.recvRanges = append(sp.recvRanges[:i], sp.recvRanges[i+1:]...)
	}
	sp.recvRanges = append(sp.recvRanges, pnRange{})
	copy(sp.recvRanges[i+1:], sp.recvRanges[i:])
	sp.recvRanges[i] = r
	// Cap stored ranges: keep only those near the largest received PN
	if len(sp.recvRanges) > 48 {
		cutoff := uint64(0)
		if sp.largestRecv > 20000 {
			cutoff = sp.largestRecv - 20000
		}
		keep := sp.recvRanges[:0]
		for _, rg := range sp.recvRanges {
			if rg.hi >= cutoff {
				keep = append(keep, rg)
			}
		}
		if len(keep) > 32 {
			keep = keep[len(keep)-32:]
		}
		sp.recvRanges = keep
	}
}

'''
assert anchor in s
s = s.replace(anchor, helpers + anchor, 1)

# 3. buildAckFrameLocked rewrite
old_ack_start = s.index("func (c *Conn) buildAckFrameLocked(sp *pnSpace) []byte {")
old_ack_end = s.index("func takeCryptoPiece", old_ack_start)
new_ack = '''func (c *Conn) buildAckFrameLocked(sp *pnSpace) []byte {
	if len(sp.recvRanges) == 0 {
		return nil
	}
	// recvRanges are ascending; ACK frames list ranges in descending order
	delayUs := uint64(0)
	if !sp.largestRecvTime.IsZero() {
		delayUs = uint64(time.Since(sp.largestRecvTime) / time.Microsecond)
	}
	exp := uint64(3)
	if c.myTP != nil {
		exp = c.myTP.ackDelayExponent
	}
	delay := delayUs >> exp
	n := len(sp.recvRanges)
	top := sp.recvRanges[n-1]
	out := []byte{0x02}
	out = appendVarint(out, top.hi)
	out = appendVarint(out, delay)
	out = appendVarint(out, uint64(n-1))
	out = appendVarint(out, top.hi-top.lo)
	for i := n - 2; i >= 0; i-- {
		prevLo := sp.recvRanges[i+1].lo
		cur := sp.recvRanges[i]
		gap := prevLo - cur.hi - 2
		out = appendVarint(out, gap)
		out = appendVarint(out, cur.hi-cur.lo)
	}
	return out
}

'''
s = s[:old_ack_start] + new_ack + s[old_ack_end:]

# 4. hasPendingLocked check
s = s.replace("len(sp.recvPNs) > 0", "len(sp.recvRanges) > 0", 1)

# 5. processPacketLocked duplicate/insert
old_dup = """	if prev, ok := sp.recvPNs[pn]; ok && prev {
		return
	}
	sp.recvPNs[pn] = true"""
assert old_dup in s
s = s.replace(old_dup, """	if sp.pnReceived(pn) {
		return
	}
	sp.pnMark(pn)""", 1)
p.write_text(s)
print("ok")
