	}
	sp.recvRanges = append(sp.recvRanges, pnRange{})
	copy(sp.recvRanges[i+1:], sp.recvRanges[i:])
	sp.recvRanges[i] = r
	// Cap stored ranges: keep only those near the largest received PN
	if len(sp.recvRanges) > 48 {
